window.KB_QUESTIONS = [{"id":"cnb_j001_q1","tid":"cnb_j001","ty":"choice","df":"basic","p":"科学观察生物时，首先要做的是？","ch":[{"key":"A","text":"只看自己喜欢的部分"},{"key":"B","text":"不写记录，全靠记忆"},{"key":"C","text":"有明确的观察目的"},{"key":"D","text":"把没看到的内容补进记录"}],"a":"C","ex":"科学观察要有目的、全面、真实，并及时记录。"},{"id":"cnb_j001_q2","tid":"cnb_j001","ty":"choice","df":"basic","p":"观察蚂蚁的外形，不适合的做法是？","ch":[{"key":"A","text":"用放大镜看口器和足"},{"key":"B","text":"从不同方向观察"},{"key":"C","text":"把看到的现象记下来"},{"key":"D","text":"把没有看清的足也写成六条"}],"a":"D","ex":"记录只能写实际观察到的现象。"},{"id":"cnb_j001_q3","tid":"cnb_j001","ty":"choice","df":"standard","p":"观察校园里的生物，较合适的一组工具是？","ch":[{"key":"A","text":"放大镜和记录本"},{"key":"B","text":"天平和量筒"},{"key":"C","text":"电压表和电流表"},{"key":"D","text":"试管和酒精灯"}],"a":"A","ex":"认识生物的外形和习性，常用放大镜，并把现象记下来。"},{"id":"cnb_j001_q4","tid":"cnb_j001","ty":"choice","df":"challenge","p":"下列做法符合科学观察要求的是？","ch":[{"key":"A","text":"只观察一次就下结论"},{"key":"B","text":"反复观察，并把现象如实记下"},{"key":"C","text":"看到的和想到的混在一起写"},{"key":"D","text":"观察时先改动生物再记录原状"}],"a":"B","ex":"观察要真实、可重复，记录的是看到的现象。"},{"id":"cnb_j002_q1","tid":"cnb_j002","ty":"choice","df":"basic","p":"下列哪一项是生物的共同特征？","ch":[{"key":"A","text":"一定由很多细胞构成"},{"key":"B","text":"都能自己制造有机物"},{"key":"C","text":"都用肺呼吸"},{"key":"D","text":"能生长和繁殖"}],"a":"D","ex":"生物都能生长、繁殖；单细胞生物、异养生物和用鳃呼吸的生物也都是生物。"},{"id":"cnb_j002_q2","tid":"cnb_j002","ty":"choice","df":"basic","p":"含羞草被碰后叶片合拢，说明生物能？","ch":[{"key":"A","text":"对外界刺激作出反应"},{"key":"B","text":"进行光合作用"},{"key":"C","text":"用种子繁殖"},{"key":"D","text":"在体外消化食物"}],"a":"A","ex":"植物受到触摸后改变姿态，是对刺激作出反应。"},{"id":"cnb_j002_q3","tid":"cnb_j002","ty":"choice","df":"standard","p":"下列物体中属于生物的是？","ch":[{"key":"A","text":"机器人"},{"key":"B","text":"生石花"},{"key":"C","text":"钟乳石"},{"key":"D","text":"汽车"}],"a":"B","ex":"生石花是植物；机器人、钟乳石和汽车没有生物的生命活动。"},{"id":"cnb_j002_q4","tid":"cnb_j002","ty":"choice","df":"challenge","p":"生物体产生的后代与亲代既像又不完全一样，说明生物具有？","ch":[{"key":"A","text":"只有遗传、没有差异"},{"key":"B","text":"只按环境临时改变、不能传代"},{"key":"C","text":"遗传和变异"},{"key":"D","text":"全部性状都与亲代不同"}],"a":"C","ex":"后代保持亲代的基本特征是遗传，个体之间有差异是变异。"},{"id":"cnb_j003_q1","tid":"cnb_j003","ty":"choice","df":"basic","p":"显微镜的放大倍数等于？","ch":[{"key":"A","text":"目镜放大倍数乘物镜放大倍数"},{"key":"B","text":"目镜与物镜放大倍数之和"},{"key":"C","text":"只有物镜的放大倍数"},{"key":"D","text":"只有目镜的放大倍数"}],"a":"A","ex":"放大倍数是目镜和物镜倍数的乘积。"},{"id":"cnb_j003_q2","tid":"cnb_j003","ty":"choice","df":"basic","p":"视野中已经找到物像，但不够清晰，应调节？","ch":[{"key":"A","text":"粗准焦螺旋大幅度转动"},{"key":"B","text":"细准焦螺旋"},{"key":"C","text":"转换器换成更小的光圈"},{"key":"D","text":"反光镜换成平面镜"}],"a":"B","ex":"细准焦螺旋用来把物像调清晰；找到物像前才主要用粗准焦螺旋。"},{"id":"cnb_j003_q3","tid":"cnb_j003","ty":"choice","df":"standard","p":"目镜 10×、物镜 40× 时，显微镜的放大倍数是？","ch":[{"key":"A","text":"50 倍"},{"key":"B","text":"30 倍"},{"key":"C","text":"400 倍"},{"key":"D","text":"4 倍"}],"a":"C","ex":"10 乘 40 等于 400。"},{"id":"cnb_j003_q4","tid":"cnb_j003","ty":"choice","df":"challenge","p":"把玻片向右移动，视野里的物像会？","ch":[{"key":"A","text":"向右移动"},{"key":"B","text":"停留不动"},{"key":"C","text":"先向上再向下"},{"key":"D","text":"向左移动"}],"a":"D","ex":"显微镜成的是倒像，物像移动方向与玻片移动方向相反。"},{"id":"cnb_j004_q1","tid":"cnb_j004","ty":"choice","df":"basic","p":"对细胞起支持和保护作用的结构是？","ch":[{"key":"A","text":"细胞膜"},{"key":"B","text":"细胞壁"},{"key":"C","text":"细胞核"},{"key":"D","text":"液泡"}],"a":"B","ex":"细胞壁位于植物细胞最外面，使细胞保持一定形态。"},{"id":"cnb_j004_q2","tid":"cnb_j004","ty":"choice","df":"basic","p":"植物细胞中，控制物质进出的结构是？","ch":[{"key":"A","text":"细胞壁"},{"key":"B","text":"液泡"},{"key":"C","text":"细胞膜"},{"key":"D","text":"叶绿体"}],"a":"C","ex":"细胞膜能控制物质进出细胞；细胞壁全透，不能控制物质进出。"},{"id":"cnb_j004_q3","tid":"cnb_j004","ty":"choice","df":"standard","p":"洋葱鳞片叶内表皮细胞一般看不到的结构是？","ch":[{"key":"A","text":"细胞壁"},{"key":"B","text":"细胞核"},{"key":"C","text":"液泡"},{"key":"D","text":"叶绿体"}],"a":"D","ex":"内表皮不见光，细胞中没有叶绿体；叶片绿色部分的细胞才有叶绿体。"},{"id":"cnb_j004_q4","tid":"cnb_j004","ty":"choice","df":"challenge","p":"植物细胞进行光合作用的场所是？","ch":[{"key":"A","text":"叶绿体"},{"key":"B","text":"线粒体"},{"key":"C","text":"液泡"},{"key":"D","text":"细胞膜"}],"a":"A","ex":"叶绿体中的色素能吸收光能，是光合作用的场所。"},{"id":"cnb_j005_q1","tid":"cnb_j005","ty":"choice","df":"basic","p":"人口腔上皮细胞属于？","ch":[{"key":"A","text":"植物细胞"},{"key":"B","text":"细菌细胞"},{"key":"C","text":"动物细胞"},{"key":"D","text":"病毒"}],"a":"C","ex":"人口腔上皮来自人体，用来观察动物细胞。"},{"id":"cnb_j005_q2","tid":"cnb_j005","ty":"choice","df":"basic","p":"动物细胞和植物细胞都有的结构是？","ch":[{"key":"A","text":"细胞壁、叶绿体、液泡"},{"key":"B","text":"只共有细胞壁"},{"key":"C","text":"只共有叶绿体"},{"key":"D","text":"细胞膜、细胞质、细胞核"}],"a":"D","ex":"动植物细胞都有细胞膜、细胞质和细胞核。"},{"id":"cnb_j005_q3","tid":"cnb_j005","ty":"choice","df":"standard","p":"与植物细胞相比，动物细胞没有的结构是？","ch":[{"key":"A","text":"细胞壁、叶绿体和液泡"},{"key":"B","text":"细胞膜和细胞质"},{"key":"C","text":"细胞核和线粒体"},{"key":"D","text":"只有细胞核"}],"a":"A","ex":"动物细胞没有细胞壁、叶绿体，也没有植物细胞那样的大液泡。"},{"id":"cnb_j005_q4","tid":"cnb_j005","ty":"choice","df":"challenge","p":"观察人口腔上皮细胞时，在载玻片上滴的是？","ch":[{"key":"A","text":"清水"},{"key":"B","text":"生理盐水"},{"key":"C","text":"碘酒原液当唯一液体"},{"key":"D","text":"酒精"}],"a":"B","ex":"生理盐水有助于保持动物细胞的正常形态；滴清水会使细胞吸水涨破。"},{"id":"cnb_j006_q1","tid":"cnb_j006","ty":"choice","df":"basic","p":"细胞中的遗传信息主要储存在？","ch":[{"key":"A","text":"细胞膜"},{"key":"B","text":"细胞壁"},{"key":"C","text":"液泡"},{"key":"D","text":"细胞核"}],"a":"D","ex":"细胞核含有遗传物质，是遗传信息库。"},{"id":"cnb_j006_q2","tid":"cnb_j006","ty":"choice","df":"basic","p":"把有机物里的化学能释放出来，供细胞利用的结构主要是？","ch":[{"key":"A","text":"线粒体"},{"key":"B","text":"叶绿体"},{"key":"C","text":"液泡"},{"key":"D","text":"细胞壁"}],"a":"A","ex":"线粒体是呼吸作用的主要场所，能分解有机物、释放能量。"},{"id":"cnb_j006_q3","tid":"cnb_j006","ty":"choice","df":"standard","p":"克隆羊多莉的遗传性状主要像提供细胞核的母羊，说明？","ch":[{"key":"A","text":"细胞膜决定所有性状"},{"key":"B","text":"细胞核控制着生物的发育和遗传"},{"key":"C","text":"细胞质中没有遗传物质所以与遗传无关"},{"key":"D","text":"细胞壁里有全部遗传信息"}],"a":"B","ex":"多莉的性状与供核母羊一致，说明细胞核是遗传控制中心。"},{"id":"cnb_j006_q4","tid":"cnb_j006","ty":"choice","df":"challenge","p":"叶绿体和线粒体都被称为能量转换器，区别是？","ch":[{"key":"A","text":"两者都只能储存光能"},{"key":"B","text":"两者都只存在于动物细胞"},{"key":"C","text":"叶绿体把光能变成化学能，线粒体把化学能释放出来"},{"key":"D","text":"线粒体制造有机物，叶绿体分解有机物"}],"a":"C","ex":"叶绿体在光下制造有机物并储存能量；线粒体分解有机物、释放能量。"},{"id":"cnb_j007_q1","tid":"cnb_j007","ty":"choice","df":"basic","p":"细胞分裂产生的新细胞，染色体数目与原细胞相比？","ch":[{"key":"A","text":"相同"},{"key":"B","text":"一定减半"},{"key":"C","text":"一定加倍"},{"key":"D","text":"随机增减"}],"a":"A","ex":"染色体先复制，再平均进入两个新细胞，数目保持不变。"},{"id":"cnb_j007_q2","tid":"cnb_j007","ty":"choice","df":"basic","p":"细胞分裂时，染色体的变化是？","ch":[{"key":"A","text":"不复制就直接分开"},{"key":"B","text":"先复制，再平均分配"},{"key":"C","text":"只复制不分开"},{"key":"D","text":"随机分到一个新细胞"}],"a":"B","ex":"复制后再均分，两个新细胞才能得到同样的遗传物质。"},{"id":"cnb_j007_q3","tid":"cnb_j007","ty":"choice","df":"standard","p":"植物细胞分裂末期，在细胞中央形成的是？","ch":[{"key":"A","text":"新的叶绿体和液泡"},{"key":"B","text":"只形成细胞核、不再分细胞质"},{"key":"C","text":"新的细胞膜和细胞壁"},{"key":"D","text":"一整块骨骼"}],"a":"C","ex":"植物细胞的细胞质分成两份后，中央长出新的细胞膜和细胞壁。"},{"id":"cnb_j007_q4","tid":"cnb_j007","ty":"choice","df":"challenge","p":"一个细胞经连续两次分裂，若不计死亡，可以得到？","ch":[{"key":"A","text":"2 个细胞"},{"key":"B","text":"3 个细胞"},{"key":"C","text":"8 个细胞"},{"key":"D","text":"4 个细胞"}],"a":"D","ex":"一次分裂由 1 个变成 2 个，再分裂一次变成 4 个。"},{"id":"cnb_j008_q1","tid":"cnb_j008","ty":"choice","df":"basic","p":"人体的结构层次由小到大是？","ch":[{"key":"A","text":"细胞、器官、组织、系统、人体"},{"key":"B","text":"细胞、组织、器官、系统、人体"},{"key":"C","text":"组织、细胞、系统、器官、人体"},{"key":"D","text":"系统、器官、组织、细胞、人体"}],"a":"B","ex":"细胞形成组织，组织形成器官，器官形成系统，系统构成人体。"},{"id":"cnb_j008_q2","tid":"cnb_j008","ty":"choice","df":"basic","p":"人的胃属于？","ch":[{"key":"A","text":"组织"},{"key":"B","text":"系统"},{"key":"C","text":"器官"},{"key":"D","text":"细胞"}],"a":"C","ex":"胃由几种组织按一定次序组成，能完成消化等功能，是器官。"},{"id":"cnb_j008_q3","tid":"cnb_j008","ty":"choice","df":"standard","p":"下列属于结缔组织的是？","ch":[{"key":"A","text":"神经"},{"key":"B","text":"骨骼肌"},{"key":"C","text":"皮肤表皮"},{"key":"D","text":"血液"}],"a":"D","ex":"血液是结缔组织；上皮组织、肌肉组织和神经组织是另外三类基本组织。"},{"id":"cnb_j008_q4","tid":"cnb_j008","ty":"choice","df":"challenge","p":"人体中，由心脏、血管和血液按一定次序组成的是？","ch":[{"key":"A","text":"循环系统"},{"key":"B","text":"一个器官"},{"key":"C","text":"一种组织"},{"key":"D","text":"一个细胞"}],"a":"A","ex":"心脏、血管等器官与血液配合，构成循环系统。"},{"id":"cnb_j009_q1","tid":"cnb_j009","ty":"choice","df":"basic","p":"植物体的结构层次一般是？","ch":[{"key":"A","text":"细胞、组织、器官、系统、植物体"},{"key":"B","text":"组织、细胞、系统、植物体"},{"key":"C","text":"细胞、组织、器官、植物体"},{"key":"D","text":"器官、组织、细胞、植物体"}],"a":"C","ex":"植物没有系统这一层次，器官直接构成植物体。"},{"id":"cnb_j009_q2","tid":"cnb_j009","ty":"choice","df":"basic","p":"绿色开花植物的营养器官是？","ch":[{"key":"A","text":"花、果实、种子"},{"key":"B","text":"只有花和果实"},{"key":"C","text":"只有种子"},{"key":"D","text":"根、茎、叶"}],"a":"D","ex":"根、茎、叶与营养有关；花、果实、种子与生殖有关。"},{"id":"cnb_j009_q3","tid":"cnb_j009","ty":"choice","df":"standard","p":"番茄的果肉主要属于？","ch":[{"key":"A","text":"营养组织"},{"key":"B","text":"保护组织"},{"key":"C","text":"分生组织"},{"key":"D","text":"输导组织"}],"a":"A","ex":"果肉细胞壁薄、液泡大，储存营养物质，属于营养组织。"},{"id":"cnb_j009_q4","tid":"cnb_j009","ty":"choice","df":"challenge","p":"植物体内运输水和无机盐的结构属于？","ch":[{"key":"A","text":"保护组织"},{"key":"B","text":"输导组织"},{"key":"C","text":"分生组织"},{"key":"D","text":"上皮组织"}],"a":"B","ex":"导管等输导组织运输水分和无机盐；上皮组织是动物组织。"},{"id":"cnb_j010_q1","tid":"cnb_j010","ty":"choice","df":"basic","p":"草履虫整个身体由几个细胞构成？","ch":[{"key":"A","text":"2 个"},{"key":"B","text":"无数个、没有细胞界限"},{"key":"C","text":"没有细胞"},{"key":"D","text":"1 个"}],"a":"D","ex":"草履虫是单细胞生物，一个细胞就是一个个体。"},{"id":"cnb_j010_q2","tid":"cnb_j010","ty":"choice","df":"basic","p":"草履虫在水中运动，依靠的是？","ch":[{"key":"A","text":"纤毛"},{"key":"B","text":"鞭毛和伪足一起"},{"key":"C","text":"肌肉"},{"key":"D","text":"鳍"}],"a":"A","ex":"草履虫体表的纤毛摆动，使它旋转前进。"},{"id":"cnb_j010_q3","tid":"cnb_j010","ty":"choice","df":"standard","p":"下列都是单细胞生物的一组是？","ch":[{"key":"A","text":"水绵、葫芦藓、肾蕨"},{"key":"B","text":"酵母菌、衣藻、草履虫"},{"key":"C","text":"蚯蚓、蝗虫、鲫鱼"},{"key":"D","text":"松树、玉米、向日葵"}],"a":"B","ex":"酵母菌、衣藻和草履虫都由一个细胞构成；其余各组是多细胞生物。"},{"id":"cnb_j010_q4","tid":"cnb_j010","ty":"choice","df":"challenge","p":"单细胞生物能够独立生活，说明？","ch":[{"key":"A","text":"只有多细胞生物才有生命活动"},{"key":"B","text":"细胞必须组成系统才能存活"},{"key":"C","text":"一个细胞就能完成营养、呼吸、排泄、运动和生殖等生命活动"},{"key":"D","text":"单细胞生物没有细胞膜"}],"a":"C","ex":"细胞是生命活动的基本单位，单细胞生物用一个细胞完成这些活动。"},{"id":"cnb_j011_q1","tid":"cnb_j011","ty":"choice","df":"basic","p":"藻类植物的主要特点是？","ch":[{"key":"A","text":"没有根、茎、叶的分化"},{"key":"B","text":"有真正的根、茎、叶"},{"key":"C","text":"用种子繁殖"},{"key":"D","text":"全部生活在干旱的沙漠表面"}],"a":"A","ex":"藻类结构简单，大多生活在水中，全身都能吸收水分和无机盐。"},{"id":"cnb_j011_q2","tid":"cnb_j011","ty":"choice","df":"basic","p":"苔藓植物可以作为监测空气污染的指示植物，主要因为？","ch":[{"key":"A","text":"它有发达的输导组织"},{"key":"B","text":"叶很薄，有毒气体容易进入"},{"key":"C","text":"它靠种子度过不良环境"},{"key":"D","text":"它只生活在深水中"}],"a":"B","ex":"苔藓的叶通常只由一层细胞构成，对有毒气体敏感。"},{"id":"cnb_j011_q3","tid":"cnb_j011","ty":"choice","df":"standard","p":"蕨类植物与苔藓植物相比，更适应陆地生活的重要原因是？","ch":[{"key":"A","text":"没有根，只有假根"},{"key":"B","text":"用种子繁殖"},{"key":"C","text":"有根、茎、叶的分化，并有输导组织"},{"key":"D","text":"细胞里没有叶绿体"}],"a":"C","ex":"输导组织能运输水分和有机物，根能固定植物并吸收水分。"},{"id":"cnb_j011_q4","tid":"cnb_j011","ty":"choice","df":"challenge","p":"葫芦藓吸收水分和无机盐，主要依靠？","ch":[{"key":"A","text":"假根"},{"key":"B","text":"导管"},{"key":"C","text":"种子"},{"key":"D","text":"叶"}],"a":"D","ex":"假根主要起固定作用；叶通常只有一层细胞，吸收水分和无机盐主要靠叶。"},{"id":"cnb_j012_q1","tid":"cnb_j012","ty":"choice","df":"basic","p":"种子植物包括？","ch":[{"key":"A","text":"藻类和蕨类"},{"key":"B","text":"裸子植物和被子植物"},{"key":"C","text":"只有被子植物，不包括松树"},{"key":"D","text":"苔藓和蕨类"}],"a":"B","ex":"种子植物用种子繁殖，分为种子裸露的裸子植物和种子有果皮包被的被子植物。"},{"id":"cnb_j012_q2","tid":"cnb_j012","ty":"choice","df":"basic","p":"松树的种子外面没有果皮包被，它属于？","ch":[{"key":"A","text":"被子植物"},{"key":"B","text":"蕨类植物"},{"key":"C","text":"裸子植物"},{"key":"D","text":"苔藓植物"}],"a":"C","ex":"银杏、松、杉、苏铁等种子裸露，是裸子植物。"},{"id":"cnb_j012_q3","tid":"cnb_j012","ty":"choice","df":"standard","p":"桃的食用部分主要由什么发育而来？","ch":[{"key":"A","text":"胚珠"},{"key":"B","text":"花粉"},{"key":"C","text":"花瓣"},{"key":"D","text":"子房壁"}],"a":"D","ex":"受精后子房发育成果实，子房壁发育成果皮，胚珠发育成种子。"},{"id":"cnb_j012_q4","tid":"cnb_j012","ty":"choice","df":"challenge","p":"种子植物比蕨类植物更适于干旱陆地的主要原因是？","ch":[{"key":"A","text":"用种子繁殖，受精过程脱离了水的限制"},{"key":"B","text":"没有叶绿体，不需要水"},{"key":"C","text":"靠孢子直接在干燥空气中受精"},{"key":"D","text":"没有根和叶，水分散失少"}],"a":"A","ex":"种子有种皮保护，胚有营养储备；花粉管使受精可以不依赖外界的水。"},{"id":"cnb_j013_q1","tid":"cnb_j013","ty":"choice","df":"basic","p":"无脊椎动物的共同特点是？","ch":[{"key":"A","text":"都用肺呼吸"},{"key":"B","text":"都有外骨骼"},{"key":"C","text":"身体内没有由脊椎骨组成的脊柱"},{"key":"D","text":"都生活在海水里"}],"a":"C","ex":"无脊椎动物种类很多，共同之处是体内没有脊柱。"},{"id":"cnb_j013_q2","tid":"cnb_j013","ty":"choice","df":"basic","p":"水螅抓住猎物，依靠的是？","ch":[{"key":"A","text":"外骨骼"},{"key":"B","text":"贝壳"},{"key":"C","text":"脊椎"},{"key":"D","text":"刺细胞"}],"a":"D","ex":"腔肠动物（刺胞动物）有刺细胞，用来捕食和防御。"},{"id":"cnb_j013_q3","tid":"cnb_j013","ty":"choice","df":"standard","p":"蝗虫能够在陆地上防止水分散失，与哪一结构有关？","ch":[{"key":"A","text":"外骨骼"},{"key":"B","text":"湿润的皮肤"},{"key":"C","text":"贝壳里的珍珠层"},{"key":"D","text":"脊椎骨"}],"a":"A","ex":"节肢动物的外骨骼可以保护身体，并减少水分蒸发。"},{"id":"cnb_j013_q4","tid":"cnb_j013","ty":"choice","df":"challenge","p":"身体由许多相似体节构成、靠刚毛和肌肉配合运动的动物是？","ch":[{"key":"A","text":"水母"},{"key":"B","text":"蚯蚓"},{"key":"C","text":"蜗牛"},{"key":"D","text":"蛔虫"}],"a":"B","ex":"蚯蚓是环节动物，身体分节，腹面有刚毛。"},{"id":"cnb_j014_q1","tid":"cnb_j014","ty":"choice","df":"basic","p":"鱼在水中呼吸，进行气体交换的结构是？","ch":[{"key":"A","text":"肺"},{"key":"B","text":"皮肤上的鳞片"},{"key":"C","text":"鳍"},{"key":"D","text":"鳃"}],"a":"D","ex":"水从口进入，经过鳃丝时完成气体交换。"},{"id":"cnb_j014_q2","tid":"cnb_j014","ty":"choice","df":"basic","p":"鱼的鳍的主要作用是？","ch":[{"key":"A","text":"游泳并保持平衡"},{"key":"B","text":"呼吸"},{"key":"C","text":"产生卵细胞"},{"key":"D","text":"吸收阳光制造有机物"}],"a":"A","ex":"胸鳍、腹鳍、尾鳍等配合，使鱼能够游动和转向。"},{"id":"cnb_j014_q3","tid":"cnb_j014","ty":"choice","df":"standard","p":"鲫鱼身体两侧的侧线能？","ch":[{"key":"A","text":"代替鳃呼吸"},{"key":"B","text":"感知水流方向和压力"},{"key":"C","text":"分泌消化酶"},{"key":"D","text":"进行光合作用"}],"a":"B","ex":"侧线是鱼的感觉器官，能测定方位和水压。"},{"id":"cnb_j014_q4","tid":"cnb_j014","ty":"choice","df":"challenge","p":"下列动物用鳃呼吸、用鳍游泳、体表常覆鳞片的是？","ch":[{"key":"A","text":"海豚"},{"key":"B","text":"青蛙"},{"key":"C","text":"鲫鱼"},{"key":"D","text":"扬子鳄"}],"a":"C","ex":"鲫鱼是鱼类。海豚用肺呼吸、胎生哺乳；青蛙和扬子鳄也不是鱼。"},{"id":"cnb_j015_q1","tid":"cnb_j015","ty":"choice","df":"basic","p":"青蛙的成体可以在陆地生活，呼吸时主要依靠？","ch":[{"key":"A","text":"肺，并靠皮肤辅助"},{"key":"B","text":"只靠鳃"},{"key":"C","text":"只靠气囊"},{"key":"D","text":"只靠体表的角质鳞片"}],"a":"A","ex":"成蛙用肺呼吸，湿润的皮肤也能辅助呼吸。"},{"id":"cnb_j015_q2","tid":"cnb_j015","ty":"choice","df":"basic","p":"蝌蚪的呼吸器官是？","ch":[{"key":"A","text":"肺和气囊"},{"key":"B","text":"鳃"},{"key":"C","text":"角质甲"},{"key":"D","text":"乳腺"}],"a":"B","ex":"蝌蚪生活在水中，用鳃呼吸，发育为成蛙后才主要用肺。"},{"id":"cnb_j015_q3","tid":"cnb_j015","ty":"choice","df":"standard","p":"爬行动物真正适应陆地生活，与哪一项有关？","ch":[{"key":"A","text":"幼体必须在水中用鳃呼吸"},{"key":"B","text":"皮肤裸露并保持湿润"},{"key":"C","text":"体表有角质鳞片或甲，卵有坚韧的卵壳"},{"key":"D","text":"生殖和发育都离不开水"}],"a":"C","ex":"角质覆盖物减少水分散失，卵壳使胚胎发育可以脱离水。"},{"id":"cnb_j015_q4","tid":"cnb_j015","ty":"choice","df":"challenge","p":"下列配对正确的是？","ch":[{"key":"A","text":"青蛙是爬行动物"},{"key":"B","text":"蛇是两栖动物"},{"key":"C","text":"龟用鳃呼吸、属于鱼类"},{"key":"D","text":"大鲵是两栖动物，扬子鳄是爬行动物"}],"a":"D","ex":"大鲵幼体水生、成体可上陆，是两栖动物；扬子鳄体表有角质覆盖，是爬行动物。"},{"id":"cnb_j016_q1","tid":"cnb_j016","ty":"choice","df":"basic","p":"鸟类呼吸的特点是？","ch":[{"key":"A","text":"只用气囊进行气体交换"},{"key":"B","text":"气体两次经过肺，气囊辅助呼吸"},{"key":"C","text":"用鳃呼吸"},{"key":"D","text":"只用皮肤呼吸"}],"a":"B","ex":"肺是气体交换的场所，气囊储存空气，使吸气和呼气时都有气流过肺。"},{"id":"cnb_j016_q2","tid":"cnb_j016","ty":"choice","df":"basic","p":"家鸽的体温？","ch":[{"key":"A","text":"随环境温度明显变化"},{"key":"B","text":"只有飞行时才恒定"},{"key":"C","text":"恒定"},{"key":"D","text":"与鱼类一样不恒定"}],"a":"C","ex":"鸟类和哺乳动物是恒温动物。"},{"id":"cnb_j016_q3","tid":"cnb_j016","ty":"choice","df":"standard","p":"哺乳动物特有的生殖发育方式是？","ch":[{"key":"A","text":"全部卵生且不哺乳"},{"key":"B","text":"变态发育"},{"key":"C","text":"体外受精、水中发育"},{"key":"D","text":"胎生、哺乳"}],"a":"D","ex":"绝大多数哺乳动物胎生，并用乳汁哺育幼崽。"},{"id":"cnb_j016_q4","tid":"cnb_j016","ty":"choice","df":"challenge","p":"下列关于鲸的判断正确的是？","ch":[{"key":"A","text":"鲸用肺呼吸、胎生哺乳，是哺乳动物"},{"key":"B","text":"鲸用鳃呼吸，是鱼类"},{"key":"C","text":"鲸体表有羽毛，是鸟类"},{"key":"D","text":"鲸幼体用鳃、成体用肺，是两栖动物"}],"a":"A","ex":"鲸生活在水中，但具有哺乳动物的特征，不是鱼。"},{"id":"cnb_j017_q1","tid":"cnb_j017","ty":"choice","df":"basic","p":"由一个细菌或真菌繁殖后形成的、肉眼可见的集合体叫做？","ch":[{"key":"A","text":"组织"},{"key":"B","text":"器官"},{"key":"C","text":"菌落"},{"key":"D","text":"孢子植物"}],"a":"C","ex":"菌落是肉眼可见的微生物集团，不同菌落的形态、颜色可以不同。"},{"id":"cnb_j017_q2","tid":"cnb_j017","ty":"choice","df":"basic","p":"培养细菌、真菌前，对培养基和培养皿进行高温处理，是为了？","ch":[{"key":"A","text":"增加营养"},{"key":"B","text":"降低温度让微生物立刻繁殖"},{"key":"C","text":"把细菌变成真菌"},{"key":"D","text":"灭菌"}],"a":"D","ex":"高温灭菌是为了杀死原有的细菌和真菌，避免干扰实验结果。"},{"id":"cnb_j017_q3","tid":"cnb_j017","ty":"choice","df":"standard","p":"检测不同环境中的细菌和真菌，接种之后一般还要？","ch":[{"key":"A","text":"在适宜温度下培养"},{"key":"B","text":"立刻冷冻并停止观察"},{"key":"C","text":"放在火焰上持续灼烧"},{"key":"D","text":"打开盖子让灰尘一直落入"}],"a":"A","ex":"恒温培养一段时间后，才能看到菌落。"},{"id":"cnb_j017_q4","tid":"cnb_j017","ty":"choice","df":"challenge","p":"下列现象能说明微生物分布广泛的是？","ch":[{"key":"A","text":"只有土壤里才有细菌"},{"key":"B","text":"未洗手的手指在培养基上按一下，培养后出现菌落"},{"key":"C","text":"煮沸后的培养基敞口放久了仍永远无菌"},{"key":"D","text":"真菌只生活在动物体内"}],"a":"B","ex":"手上、空气、土壤和水中都有微生物，所以要无菌操作。"},{"id":"cnb_j018_q1","tid":"cnb_j018","ty":"choice","df":"basic","p":"细菌与酵母菌相比，结构上最主要的区别是？","ch":[{"key":"A","text":"细菌没有细胞壁"},{"key":"B","text":"细菌有叶绿体"},{"key":"C","text":"细菌由多个细胞构成"},{"key":"D","text":"细菌没有成形的细胞核"}],"a":"D","ex":"细菌是原核生物；酵母菌是真菌，有成形的细胞核。"},{"id":"cnb_j018_q2","tid":"cnb_j018","ty":"choice","df":"basic","p":"细菌的生殖方式是？","ch":[{"key":"A","text":"分裂生殖"},{"key":"B","text":"种子繁殖"},{"key":"C","text":"产卵"},{"key":"D","text":"出芽形成果实"}],"a":"A","ex":"一个细菌分裂成两个，在适宜条件下繁殖很快。"},{"id":"cnb_j018_q3","tid":"cnb_j018","ty":"choice","df":"standard","p":"芽孢是细菌的？","ch":[{"key":"A","text":"生殖细胞"},{"key":"B","text":"休眠体"},{"key":"C","text":"运动器官"},{"key":"D","text":"叶绿体"}],"a":"B","ex":"环境恶劣时细菌形成芽孢度过不良环境，条件适宜再萌发，芽孢不是生殖细胞。"},{"id":"cnb_j018_q4","tid":"cnb_j018","ty":"choice","df":"challenge","p":"大多数细菌的营养方式是？","ch":[{"key":"A","text":"像绿色植物一样自养"},{"key":"B","text":"寄生在死细胞里进行光合作用"},{"key":"C","text":"异养，不能自己制造有机物"},{"key":"D","text":"只吸收阳光、不需要有机物"}],"a":"C","ex":"多数细菌没有叶绿体，靠分解现成的有机物生活；少数细菌可以自养。"},{"id":"cnb_j019_q1","tid":"cnb_j019","ty":"choice","df":"basic","p":"蘑菇、酵母菌和霉菌都属于？","ch":[{"key":"A","text":"真菌"},{"key":"B","text":"细菌"},{"key":"C","text":"病毒"},{"key":"D","text":"藻类植物"}],"a":"A","ex":"它们都有成形的细胞核，主要靠菌丝或单细胞吸收现成的有机物。"},{"id":"cnb_j019_q2","tid":"cnb_j019","ty":"choice","df":"basic","p":"酵母菌常用来发面，是因为它分解有机物时产生？","ch":[{"key":"A","text":"氧气"},{"key":"B","text":"二氧化碳"},{"key":"C","text":"叶绿素"},{"key":"D","text":"淀粉酶以外的蛋白质外壳"}],"a":"B","ex":"二氧化碳使面团膨胀；酿酒时则主要利用酵母菌产生的酒精。"},{"id":"cnb_j019_q3","tid":"cnb_j019","ty":"choice","df":"standard","p":"蘑菇的地下菌丝主要作用是？","ch":[{"key":"A","text":"进行光合作用"},{"key":"B","text":"形成种子"},{"key":"C","text":"吸收水和有机物"},{"key":"D","text":"用刺细胞捕食"}],"a":"C","ex":"蘑菇没有叶绿体，营养菌丝从环境中吸收有机物。"},{"id":"cnb_j019_q4","tid":"cnb_j019","ty":"choice","df":"challenge","p":"制作馒头时酵母菌起作用，这一做法属于？","ch":[{"key":"A","text":"用病毒固定太阳能"},{"key":"B","text":"让细菌进行光合作用"},{"key":"C","text":"用藻类产生酒精"},{"key":"D","text":"利用真菌制作发酵食品"}],"a":"D","ex":"发酵食品制作是用微生物把原料转变成食品的常见做法。"},{"id":"cnb_j020_q1","tid":"cnb_j020","ty":"choice","df":"basic","p":"病毒的结构通常包括？","ch":[{"key":"A","text":"细胞壁、细胞膜和细胞核"},{"key":"B","text":"蛋白质外壳和内部的遗传物质"},{"key":"C","text":"菌丝和孢子"},{"key":"D","text":"根、茎、叶"}],"a":"B","ex":"病毒没有细胞结构，由蛋白质外壳和遗传物质组成。"},{"id":"cnb_j020_q2","tid":"cnb_j020","ty":"choice","df":"basic","p":"病毒的生活方式是？","ch":[{"key":"A","text":"可以在任何死细胞和清水中独立繁殖"},{"key":"B","text":"像植物一样自养"},{"key":"C","text":"必须寄生在活细胞里"},{"key":"D","text":"在培养基上形成菌落后独立生活"}],"a":"C","ex":"病毒不能独立完成生命活动，离开活细胞一般就停止活动。"},{"id":"cnb_j020_q3","tid":"cnb_j020","ty":"choice","df":"standard","p":"病毒产生后代的方式是？","ch":[{"key":"A","text":"分裂成两个细胞"},{"key":"B","text":"开花结果"},{"key":"C","text":"产下受精卵"},{"key":"D","text":"自我复制"}],"a":"D","ex":"病毒利用寄主细胞的物质，复制出新的病毒。"},{"id":"cnb_j020_q4","tid":"cnb_j020","ty":"choice","df":"challenge","p":"下列利用病毒的做法是？","ch":[{"key":"A","text":"用减毒或灭活的病毒制成疫苗"},{"key":"B","text":"用病毒代替叶绿体制造淀粉"},{"key":"C","text":"用病毒把面团发起来"},{"key":"D","text":"用病毒在土壤里分解落叶"}],"a":"A","ex":"疫苗可以刺激人体产生抵抗相应病原体的能力；分解落叶的主要是细菌和真菌。"},{"id":"cnb_j021_q1","tid":"cnb_j021","ty":"choice","df":"basic","p":"对生物进行分类，主要依据是？","ch":[{"key":"A","text":"发现的先后顺序"},{"key":"B","text":"个体的大小"},{"key":"C","text":"形态结构等特征"},{"key":"D","text":"生活地区的名称"}],"a":"C","ex":"分类要比较生物的形态、结构和生理特征，而不是按名字或发现顺序。"},{"id":"cnb_j021_q2","tid":"cnb_j021","ty":"choice","df":"basic","p":"把小麦、银杏、葫芦藓、水绵分成一类「植物」，依据的是它们？","ch":[{"key":"A","text":"都用种子繁殖"},{"key":"B","text":"都有果实"},{"key":"C","text":"都生活在水中"},{"key":"D","text":"都能进行光合作用，属于植物"}],"a":"D","ex":"这四种生物营养方式都是自养，但繁殖方式和结构层次并不相同。"},{"id":"cnb_j021_q3","tid":"cnb_j021","ty":"choice","df":"standard","p":"使用检索表时，正确的做法是？","ch":[{"key":"A","text":"按特征逐条选择，直到找出名称"},{"key":"B","text":"只看最后一行"},{"key":"C","text":"按页码从小到大随便选"},{"key":"D","text":"先假定名称再倒着改特征"}],"a":"A","ex":"检索表每次根据一个或一组特征分成两支，顺着符合的一支继续查。"},{"id":"cnb_j021_q4","tid":"cnb_j021","ty":"choice","df":"challenge","p":"把蝙蝠分到哺乳动物而不是鸟类，关键特征是？","ch":[{"key":"A","text":"会飞"},{"key":"B","text":"胎生、哺乳，没有羽毛"},{"key":"C","text":"体温恒定"},{"key":"D","text":"生活在夜间"}],"a":"B","ex":"会飞和恒温不是鸟类独有；蝙蝠有毛、胎生哺乳。"},{"id":"cnb_j022_q1","tid":"cnb_j022","ty":"choice","df":"basic","p":"生物分类的单位从大到小依次是？","ch":[{"key":"A","text":"种、属、科、目、纲、门、界"},{"key":"B","text":"界、纲、门、科、目、属、种"},{"key":"C","text":"门、界、纲、科、属、目、种"},{"key":"D","text":"界、门、纲、目、科、属、种"}],"a":"D","ex":"等级越大，包含的生物越多，共同特征越少。"},{"id":"cnb_j022_q2","tid":"cnb_j022","ty":"choice","df":"basic","p":"最基本的分类单位是？","ch":[{"key":"A","text":"种"},{"key":"B","text":"界"},{"key":"C","text":"门"},{"key":"D","text":"科"}],"a":"A","ex":"同种生物的亲缘关系最近，共同特征最多。"},{"id":"cnb_j022_q3","tid":"cnb_j022","ty":"choice","df":"standard","p":"马和驴能够交配产下骡，但骡通常不能生育。马和驴属于？","ch":[{"key":"A","text":"同一种生物"},{"key":"B","text":"同属的不同种"},{"key":"C","text":"不同界的生物"},{"key":"D","text":"没有分类关系"}],"a":"B","ex":"马和驴的属名相同、种加词不同，亲缘关系较近，但不是同一个种。"},{"id":"cnb_j022_q4","tid":"cnb_j022","ty":"choice","df":"challenge","p":"分类单位越小，同一单位中的生物？","ch":[{"key":"A","text":"共同特征越少"},{"key":"B","text":"一定生活在同一个省"},{"key":"C","text":"共同特征越多"},{"key":"D","text":"个体数量一定更多"}],"a":"C","ex":"种比属小，同种生物的共同特征比同属生物更多。"},{"id":"cnb_j023_q1","tid":"cnb_j023","ty":"choice","df":"basic","p":"种子萌发所需的环境条件是？","ch":[{"key":"A","text":"适宜的温度、一定的水分和充足的空气"},{"key":"B","text":"只需要光照"},{"key":"C","text":"只需要土壤中的有机肥"},{"key":"D","text":"必须浸泡在煮沸后密闭的水里"}],"a":"A","ex":"胚是活的、完整的，并已度过休眠期，再加上适宜的外界条件，种子才能萌发。"},{"id":"cnb_j023_q2","tid":"cnb_j023","ty":"choice","df":"basic","p":"种子萌发时，最先突破种皮的是？","ch":[{"key":"A","text":"胚芽"},{"key":"B","text":"胚根"},{"key":"C","text":"叶"},{"key":"D","text":"果实"}],"a":"B","ex":"胚根发育成根，先固定植物并吸收水分。"},{"id":"cnb_j023_q3","tid":"cnb_j023","ty":"choice","df":"standard","p":"测定种子发芽率时，应选择？","ch":[{"key":"A","text":"只挑一粒种子"},{"key":"B","text":"已经霉变的种子"},{"key":"C","text":"粒大饱满、储存时间短的种子重复试验"},{"key":"D","text":"煮熟后的种子"}],"a":"C","ex":"重复实验并选用有活力的种子，结果才可靠；煮熟的种子胚已死亡。"},{"id":"cnb_j023_q4","tid":"cnb_j023","ty":"choice","df":"challenge","p":"把种子放在潮湿但密闭、没有空气的环境中，通常？","ch":[{"key":"A","text":"萌发得更快"},{"key":"B","text":"只长叶不长根"},{"key":"C","text":"一定长成完整植株"},{"key":"D","text":"不能正常萌发"}],"a":"D","ex":"胚进行呼吸需要氧气，缺少空气时种子不能正常萌发。"},{"id":"cnb_j024_q1","tid":"cnb_j024","ty":"choice","df":"basic","p":"根吸收水分和无机盐的主要部位是？","ch":[{"key":"A","text":"根冠"},{"key":"B","text":"成熟区"},{"key":"C","text":"分生区"},{"key":"D","text":"伸长区的最前端、还没有根毛"}],"a":"B","ex":"成熟区生有大量根毛，增大了吸收面积。"},{"id":"cnb_j024_q2","tid":"cnb_j024","ty":"choice","df":"basic","p":"使枝叶繁茂的无机盐主要含？","ch":[{"key":"A","text":"磷"},{"key":"B","text":"钾"},{"key":"C","text":"氮"},{"key":"D","text":"只有钙"}],"a":"C","ex":"含氮的无机盐促进细胞分生和生长，使枝叶茂盛。"},{"id":"cnb_j024_q3","tid":"cnb_j024","ty":"choice","df":"standard","p":"根能不断长长，是因为？","ch":[{"key":"A","text":"根冠细胞不断进行光合作用"},{"key":"B","text":"成熟区细胞壁消失"},{"key":"C","text":"茎把长度直接传给根"},{"key":"D","text":"分生区细胞分裂、伸长区细胞伸长"}],"a":"D","ex":"分生区增加细胞数目，伸长区使新细胞体积变大。"},{"id":"cnb_j024_q4","tid":"cnb_j024","ty":"choice","df":"challenge","p":"植物缺钾时，较常见的表现是？","ch":[{"key":"A","text":"茎秆软弱，容易倒伏"},{"key":"B","text":"只影响开花、茎秆反而更硬"},{"key":"C","text":"叶片立刻失去全部细胞"},{"key":"D","text":"根毛变成叶绿体"}],"a":"A","ex":"钾使茎秆健壮；磷与开花结果关系密切，氮与枝叶繁茂关系密切。"},{"id":"cnb_j025_q1","tid":"cnb_j025","ty":"choice","df":"basic","p":"一朵花中，与结出果实和种子直接有关的结构是？","ch":[{"key":"A","text":"花瓣和萼片"},{"key":"B","text":"花柄和花托"},{"key":"C","text":"雄蕊和雌蕊"},{"key":"D","text":"只有花瓣"}],"a":"C","ex":"雄蕊产生花粉，雌蕊中的子房将来发育成果实。"},{"id":"cnb_j025_q2","tid":"cnb_j025","ty":"choice","df":"basic","p":"花粉落到雌蕊柱头上的过程叫做？","ch":[{"key":"A","text":"受精"},{"key":"B","text":"蒸腾"},{"key":"C","text":"呼吸"},{"key":"D","text":"传粉"}],"a":"D","ex":"花粉管中的精子与卵细胞结合才是受精，发生在传粉之后。"},{"id":"cnb_j025_q3","tid":"cnb_j025","ty":"choice","df":"standard","p":"受精完成后，胚珠发育成？","ch":[{"key":"A","text":"种子"},{"key":"B","text":"果实"},{"key":"C","text":"果皮"},{"key":"D","text":"花瓣"}],"a":"A","ex":"子房发育成果实，胚珠发育成种子，子房壁发育成果皮。"},{"id":"cnb_j025_q4","tid":"cnb_j025","ty":"choice","df":"challenge","p":"玉米传粉不足会出现缺粒，可以采用的办法是？","ch":[{"key":"A","text":"把根全部剪掉"},{"key":"B","text":"人工辅助授粉"},{"key":"C","text":"停止浇水"},{"key":"D","text":"摘掉全部叶片"}],"a":"B","ex":"人工把花粉撒到柱头上，可以弥补自然传粉的不足。"},{"id":"cnb_j026_q1","tid":"cnb_j026","ty":"choice","df":"basic","p":"水分在植物体内上升，主要经过？","ch":[{"key":"A","text":"筛管"},{"key":"B","text":"气孔直接进入果实"},{"key":"C","text":"花瓣的表面"},{"key":"D","text":"导管"}],"a":"D","ex":"导管把根吸收的水和无机盐向上运输；筛管主要运输有机物。"},{"id":"cnb_j026_q2","tid":"cnb_j026","ty":"choice","df":"basic","p":"蒸腾作用的水主要通过哪里散失？","ch":[{"key":"A","text":"叶片上的气孔"},{"key":"B","text":"根毛"},{"key":"C","text":"果皮"},{"key":"D","text":"种子的种皮"}],"a":"A","ex":"气孔由成对的保卫细胞围成，是水蒸气外出的门户。"},{"id":"cnb_j026_q3","tid":"cnb_j026","ty":"choice","df":"standard","p":"移栽幼苗时保留根部的土坨，是为了？","ch":[{"key":"A","text":"让叶不再进行蒸腾"},{"key":"B","text":"保护根毛，利于吸水"},{"key":"C","text":"阻止呼吸作用"},{"key":"D","text":"促使立即开花"}],"a":"B","ex":"根毛很容易受损，土坨可以保护幼根和根毛。"},{"id":"cnb_j026_q4","tid":"cnb_j026","ty":"choice","df":"challenge","p":"蒸腾作用对植物生活的意义是？","ch":[{"key":"A","text":"制造有机物并释放氧气"},{"key":"B","text":"把二氧化碳合成淀粉"},{"key":"C","text":"拉动水分和无机盐向上运输，并降低叶片温度"},{"key":"D","text":"代替根吸收无机盐"}],"a":"C","ex":"蒸腾产生的拉力促使水和无机盐上升，同时带走热量。"},{"id":"cnb_j027_q1","tid":"cnb_j027","ty":"choice","df":"basic","p":"光合作用的原料是？","ch":[{"key":"A","text":"二氧化碳和水"},{"key":"B","text":"只有氧气"},{"key":"C","text":"只有淀粉"},{"key":"D","text":"酒精和碘液"}],"a":"A","ex":"二氧化碳和水在光下、在叶绿体中转变成有机物和氧气。"},{"id":"cnb_j027_q2","tid":"cnb_j027","ty":"choice","df":"basic","p":"绿叶在光下制造有机物的实验中，滴加碘液后变蓝的部位说明产生了？","ch":[{"key":"A","text":"脂肪"},{"key":"B","text":"淀粉"},{"key":"C","text":"蛋白质"},{"key":"D","text":"二氧化碳"}],"a":"B","ex":"淀粉遇碘变蓝。遮光部分不变蓝，说明光是光合作用的必要条件。"},{"id":"cnb_j027_q3","tid":"cnb_j027","ty":"choice","df":"standard","p":"实验前把天竺葵放到黑暗处一昼夜，目的是？","ch":[{"key":"A","text":"让叶片提前变蓝"},{"key":"B","text":"杀死叶片细胞"},{"key":"C","text":"运走或耗尽叶片中原有的淀粉"},{"key":"D","text":"增加叶片中的二氧化碳储存"}],"a":"C","ex":"这样后来检测到的淀粉，才是实验过程中新制造的。"},{"id":"cnb_j027_q4","tid":"cnb_j027","ty":"choice","df":"challenge","p":"光合作用的表达式可以概括为？","ch":[{"key":"A","text":"有机物和氧气生成二氧化碳和水，不需要光"},{"key":"B","text":"水直接变成淀粉，不需要二氧化碳"},{"key":"C","text":"氧气和水生成二氧化碳"},{"key":"D","text":"二氧化碳和水在光与叶绿体的作用下生成有机物和氧气"}],"a":"D","ex":"叶绿体利用光能，把二氧化碳和水合成储存能量的有机物，并释放氧气。"},{"id":"cnb_j028_q1","tid":"cnb_j028","ty":"choice","df":"basic","p":"植物呼吸作用的主要场所是？","ch":[{"key":"A","text":"叶绿体"},{"key":"B","text":"线粒体"},{"key":"C","text":"液泡"},{"key":"D","text":"导管"}],"a":"B","ex":"活细胞的线粒体分解有机物，释放能量。"},{"id":"cnb_j028_q2","tid":"cnb_j028","ty":"choice","df":"basic","p":"呼吸作用产生的气体是？","ch":[{"key":"A","text":"只有氧气"},{"key":"B","text":"只有氮气"},{"key":"C","text":"二氧化碳"},{"key":"D","text":"一氧化碳作为主要产物"}],"a":"C","ex":"有机物被分解成二氧化碳和水，同时释放能量。"},{"id":"cnb_j028_q3","tid":"cnb_j028","ty":"choice","df":"standard","p":"储藏粮食时保持干燥、低温，是为了？","ch":[{"key":"A","text":"促进光合作用"},{"key":"B","text":"让种子立刻萌发"},{"key":"C","text":"增加氧气使呼吸更旺盛"},{"key":"D","text":"减弱种子的呼吸作用"}],"a":"D","ex":"干燥、低温使呼吸放慢，减少有机物消耗，也抑制霉菌。"},{"id":"cnb_j028_q4","tid":"cnb_j028","ty":"choice","df":"challenge","p":"绿色植物在白天？","ch":[{"key":"A","text":"同时进行光合作用和呼吸作用"},{"key":"B","text":"只进行光合作用"},{"key":"C","text":"只进行呼吸作用"},{"key":"D","text":"两种作用都停止"}],"a":"A","ex":"只要细胞是活的就进行呼吸；有光时叶肉细胞还进行光合作用。"},{"id":"cnb_j029_q1","tid":"cnb_j029","ty":"choice","df":"basic","p":"绿色植物维持生物圈碳氧平衡，主要依靠？","ch":[{"key":"A","text":"只进行呼吸作用"},{"key":"B","text":"蒸腾作用产生氧气"},{"key":"C","text":"光合作用释放氧气、吸收二氧化碳"},{"key":"D","text":"根吸收氧气"}],"a":"C","ex":"光合作用吸收的二氧化碳和释放的氧气，抵消了生物呼吸等消耗。"},{"id":"cnb_j029_q2","tid":"cnb_j029","ty":"choice","df":"basic","p":"植物参与生物圈水循环，主要依靠？","ch":[{"key":"A","text":"受精作用"},{"key":"B","text":"分裂生殖"},{"key":"C","text":"反射"},{"key":"D","text":"蒸腾作用"}],"a":"D","ex":"蒸腾把植物吸收的水分散到大气中，再以降水等形式回到地面。"},{"id":"cnb_j029_q3","tid":"cnb_j029","ty":"choice","df":"standard","p":"动物和人生命活动所需的有机物，归根到底主要来自？","ch":[{"key":"A","text":"绿色植物的光合作用"},{"key":"B","text":"土壤中的无机盐直接变成淀粉"},{"key":"C","text":"动物自己的光合作用"},{"key":"D","text":"空气中的氮气"}],"a":"A","ex":"植物制造的有机物沿食物关系传递，动物不能自己把无机物合成有机物。"},{"id":"cnb_j029_q4","tid":"cnb_j029","ty":"choice","df":"challenge","p":"如果一个地区的森林被大面积砍伐，较可能出现的是？","ch":[{"key":"A","text":"氧气立刻无限增加"},{"key":"B","text":"空气中二氧化碳增多，水土流失加重"},{"key":"C","text":"降水量一定增加且不再变化"},{"key":"D","text":"植物的蒸腾作用增强"}],"a":"B","ex":"森林减少后，吸收二氧化碳和蒸腾散水都减弱，保持水土的能力也下降。"},{"id":"cnb_j030_q1","tid":"cnb_j030","ty":"choice","df":"basic","p":"男性产生精子并分泌雄性激素的器官是？","ch":[{"key":"A","text":"卵巢"},{"key":"B","text":"子宫"},{"key":"C","text":"输卵管"},{"key":"D","text":"睾丸"}],"a":"D","ex":"睾丸是男性的主要生殖器官。"},{"id":"cnb_j030_q2","tid":"cnb_j030","ty":"choice","df":"basic","p":"女性产生卵细胞并分泌雌性激素的器官是？","ch":[{"key":"A","text":"卵巢"},{"key":"B","text":"子宫"},{"key":"C","text":"输卵管"},{"key":"D","text":"胎盘"}],"a":"A","ex":"卵巢是女性的主要生殖器官；子宫是胚胎发育的场所。"},{"id":"cnb_j030_q3","tid":"cnb_j030","ty":"choice","df":"standard","p":"精子和卵细胞结合形成受精卵的场所通常是？","ch":[{"key":"A","text":"卵巢"},{"key":"B","text":"输卵管"},{"key":"C","text":"子宫"},{"key":"D","text":"阴道"}],"a":"B","ex":"受精发生在输卵管，受精卵随后进入子宫着床。"},{"id":"cnb_j030_q4","tid":"cnb_j030","ty":"choice","df":"challenge","p":"胎儿通过什么从母体获得营养和氧气？","ch":[{"key":"A","text":"肺直接呼吸外界空气"},{"key":"B","text":"乳腺"},{"key":"C","text":"胎盘和脐带"},{"key":"D","text":"卵黄"}],"a":"C","ex":"胎儿的肺尚未承担呼吸，物质交换通过胎盘和脐带完成。"},{"id":"cnb_j031_q1","tid":"cnb_j031","ty":"choice","df":"basic","p":"青春期发育最明显的特点是？","ch":[{"key":"A","text":"身高和体重迅速增长，生殖器官发育成熟"},{"key":"B","text":"只长头发、其他器官不再变化"},{"key":"C","text":"身体停止生长"},{"key":"D","text":"全部第二性征消失"}],"a":"A","ex":"青春期是身体发育和智力发展的重要时期。"},{"id":"cnb_j031_q2","tid":"cnb_j031","ty":"choice","df":"basic","p":"男孩出现遗精、女孩出现月经，说明？","ch":[{"key":"A","text":"一定生病了"},{"key":"B","text":"生殖器官开始发育成熟，是正常生理现象"},{"key":"C","text":"生殖器官停止发育"},{"key":"D","text":"不必讲究卫生"}],"a":"B","ex":"遗精和月经是青春期的正常现象，同时要注意清洁卫生。"},{"id":"cnb_j031_q3","tid":"cnb_j031","ty":"choice","df":"standard","p":"青春期第二性征出现，与哪一类物质直接有关？","ch":[{"key":"A","text":"唾液淀粉酶"},{"key":"B","text":"血红蛋白"},{"key":"C","text":"性激素"},{"key":"D","text":"生长激素是唯一原因、与性激素无关"}],"a":"C","ex":"睾丸分泌雄性激素，卵巢分泌雌性激素，促使第二性征出现。"},{"id":"cnb_j031_q4","tid":"cnb_j031","ty":"choice","df":"challenge","p":"对待青春期的身体变化，合适的做法是？","ch":[{"key":"A","text":"因为害羞而拒绝所有卫生护理"},{"key":"B","text":"自行长期服用激素加快发育"},{"key":"C","text":"嘲笑同伴的发育差异"},{"key":"D","text":"了解科学知识，有困惑时向家长或老师求助"}],"a":"D","ex":"青春期的变化是正常的，需要科学认识和健康的生活习惯。"},{"id":"cnb_j032_q1","tid":"cnb_j032","ty":"choice","df":"basic","p":"为人体生命活动提供能量的主要物质是？","ch":[{"key":"A","text":"维生素"},{"key":"B","text":"糖类"},{"key":"C","text":"水"},{"key":"D","text":"无机盐"}],"a":"B","ex":"糖类是主要的供能物质；脂肪是备用能源，蛋白质主要用来建造和修复身体。"},{"id":"cnb_j032_q2","tid":"cnb_j032","ty":"choice","df":"basic","p":"儿童缺乏维生素 D 容易患？","ch":[{"key":"A","text":"坏血病"},{"key":"B","text":"夜盲症"},{"key":"C","text":"佝偻病"},{"key":"D","text":"脚气病"}],"a":"C","ex":"维生素 D 促进钙的吸收；缺乏维生素 A 患夜盲症，缺乏维生素 C 患坏血病，缺乏维生素 B1 患脚气病。"},{"id":"cnb_j032_q3","tid":"cnb_j032","ty":"choice","df":"standard","p":"铁是构成什么的原料？","ch":[{"key":"A","text":"甲状腺激素"},{"key":"B","text":"维生素 C"},{"key":"C","text":"淀粉"},{"key":"D","text":"血红蛋白"}],"a":"D","ex":"血红蛋白含铁，运输氧；缺铁容易贫血。"},{"id":"cnb_j032_q4","tid":"cnb_j032","ty":"choice","df":"challenge","p":"长期不吃蔬菜水果，又很少接触其他维生素 C 来源，可能引起？","ch":[{"key":"A","text":"坏血病"},{"key":"B","text":"地方性甲状腺肿"},{"key":"C","text":"夜盲症"},{"key":"D","text":"只与缺碘有关的呆小症"}],"a":"A","ex":"维生素 C 维持正常代谢，严重缺乏会患坏血病；呆小症与幼年甲状腺激素不足有关。"},{"id":"cnb_j033_q1","tid":"cnb_j033","ty":"choice","df":"basic","p":"淀粉开始被消化的部位是？","ch":[{"key":"A","text":"胃"},{"key":"B","text":"大肠"},{"key":"C","text":"口腔"},{"key":"D","text":"肝脏"}],"a":"C","ex":"唾液淀粉酶在口腔把部分淀粉分解成麦芽糖。"},{"id":"cnb_j033_q2","tid":"cnb_j033","ty":"choice","df":"basic","p":"营养物质消化和吸收的主要场所是？","ch":[{"key":"A","text":"口腔"},{"key":"B","text":"食道"},{"key":"C","text":"大肠"},{"key":"D","text":"小肠"}],"a":"D","ex":"小肠很长，内表面有皱襞和小肠绒毛，并有多种消化液。"},{"id":"cnb_j033_q3","tid":"cnb_j033","ty":"choice","df":"standard","p":"胆汁的作用是？","ch":[{"key":"A","text":"把脂肪乳化成小滴，胆汁中不含消化酶"},{"key":"B","text":"直接把淀粉分解成葡萄糖"},{"key":"C","text":"把蛋白质分解成氨基酸"},{"key":"D","text":"代替胃液消化所有食物"}],"a":"A","ex":"胆汁由肝脏分泌，乳化脂肪，便于脂肪酶发挥作用。"},{"id":"cnb_j033_q4","tid":"cnb_j033","ty":"choice","df":"challenge","p":"蛋白质开始被消化的部位是？","ch":[{"key":"A","text":"口腔"},{"key":"B","text":"胃"},{"key":"C","text":"大肠"},{"key":"D","text":"食道"}],"a":"B","ex":"胃液中的蛋白酶把蛋白质初步分解；蛋白质在小肠才被彻底分解。"},{"id":"cnb_j034_q1","tid":"cnb_j034","ty":"choice","df":"basic","p":"合理营养是指？","ch":[{"key":"A","text":"只吃肉类和精制糖"},{"key":"B","text":"每餐只吃一种食物"},{"key":"C","text":"用保健品代替全部正餐"},{"key":"D","text":"食物多样，营养比例合适，并能满足身体需要"}],"a":"D","ex":"平衡膳食要求谷薯、蔬菜水果、鱼禽肉蛋和奶豆等搭配。"},{"id":"cnb_j034_q2","tid":"cnb_j034","ty":"choice","df":"basic","p":"购买带包装的食品，首先要查看？","ch":[{"key":"A","text":"生产日期、保质期和配料"},{"key":"B","text":"只看广告语"},{"key":"C","text":"包装是否颜色鲜艳"},{"key":"D","text":"是否写着「绝对无害」却没有日期"}],"a":"A","ex":"过期或成分不清的食品不应购买。"},{"id":"cnb_j034_q3","tid":"cnb_j034","ty":"choice","df":"standard","p":"早餐只吃少量饼干就上学，上午容易能量不足。较合理的调整是？","ch":[{"key":"A","text":"用糖果完全代替正餐"},{"key":"B","text":"增加谷类、蛋奶和蔬菜水果"},{"key":"C","text":"不吃午餐把食物留到晚餐"},{"key":"D","text":"只喝碳酸饮料"}],"a":"B","ex":"谷类提供糖类，蛋奶提供蛋白质，蔬菜水果提供维生素。"},{"id":"cnb_j034_q4","tid":"cnb_j034","ty":"choice","df":"challenge","p":"绿色食品标志表示该食品？","ch":[{"key":"A","text":"一定是未加工的野果"},{"key":"B","text":"可以不看保质期"},{"key":"C","text":"产自良好生态环境、符合安全标准"},{"key":"D","text":"没有经过任何检验"}],"a":"C","ex":"绿色食品有特定标志和标准，购买时仍要看日期和保存条件。"},{"id":"cnb_j035_q1","tid":"cnb_j035","ty":"choice","df":"basic","p":"呼吸道由上到下依次包括？","ch":[{"key":"A","text":"鼻、咽、喉、气管、支气管"},{"key":"B","text":"口、食道、胃、肠"},{"key":"C","text":"肺、心脏、血管"},{"key":"D","text":"鼻、食道、气管、胃"}],"a":"A","ex":"呼吸道是气体进出肺的通道，肺是气体交换的场所。"},{"id":"cnb_j035_q2","tid":"cnb_j035","ty":"choice","df":"basic","p":"用鼻呼吸比用口呼吸好，主要因为鼻腔能？","ch":[{"key":"A","text":"直接完成全部气体交换"},{"key":"B","text":"使空气变得温暖、湿润、清洁"},{"key":"C","text":"制造氧气"},{"key":"D","text":"代替肺"}],"a":"B","ex":"鼻毛、黏液和黏膜中的毛细血管处理进入的空气。"},{"id":"cnb_j035_q3","tid":"cnb_j035","ty":"choice","df":"standard","p":"痰形成的主要部位是？","ch":[{"key":"A","text":"肺泡"},{"key":"B","text":"胃"},{"key":"C","text":"气管和支气管"},{"key":"D","text":"口腔"}],"a":"C","ex":"气管和支气管黏膜上的纤毛把黏液及灰尘推向喉部，形成痰。"},{"id":"cnb_j035_q4","tid":"cnb_j035","ty":"choice","df":"challenge","p":"吞咽时能盖住喉口、避免食物进入气管的结构是？","ch":[{"key":"A","text":"声带"},{"key":"B","text":"膈肌"},{"key":"C","text":"鼻毛"},{"key":"D","text":"会厌软骨"}],"a":"D","ex":"吞咽时喉上升，会厌软骨盖住喉口；吃饭时说笑容易使食物误入气管。"},{"id":"cnb_j036_q1","tid":"cnb_j036","ty":"choice","df":"basic","p":"人体与外界进行气体交换的主要场所是？","ch":[{"key":"A","text":"鼻腔"},{"key":"B","text":"肺"},{"key":"C","text":"气管"},{"key":"D","text":"皮肤"}],"a":"B","ex":"肺泡数量多、壁薄，外面缠着毛细血管，便于气体交换。"},{"id":"cnb_j036_q2","tid":"cnb_j036","ty":"choice","df":"basic","p":"吸气时？","ch":[{"key":"A","text":"肋间肌和膈肌舒张，胸廓缩小"},{"key":"B","text":"肺主动收缩把空气压出去"},{"key":"C","text":"肋间肌和膈肌收缩，胸廓扩大"},{"key":"D","text":"气管壁的肌肉把空气压进胃"}],"a":"C","ex":"胸廓扩大使肺扩张，肺内气压低于外界，空气进入肺。"},{"id":"cnb_j036_q3","tid":"cnb_j036","ty":"choice","df":"standard","p":"肺泡与血液之间的气体交换是？","ch":[{"key":"A","text":"两种气体都不移动"},{"key":"B","text":"氧气和二氧化碳同时进入肺泡、血液中没有变化"},{"key":"C","text":"只有氮气进行交换"},{"key":"D","text":"氧气进入血液，二氧化碳进入肺泡"}],"a":"D","ex":"交换后血液由静脉血变成动脉血。"},{"id":"cnb_j036_q4","tid":"cnb_j036","ty":"choice","df":"challenge","p":"肺泡适于气体交换的特点包括？","ch":[{"key":"A","text":"数目多、壁只由一层上皮细胞构成、外面包绕毛细血管"},{"key":"B","text":"壁很厚，外面没有血管"},{"key":"C","text":"肺泡里充满食物"},{"key":"D","text":"肺泡直接开口在皮肤表面"}],"a":"A","ex":"这些特点使气体经过的距离短、交换面积大。"},{"id":"cnb_j037_q1","tid":"cnb_j037","ty":"choice","df":"basic","p":"血液由哪两部分组成？","ch":[{"key":"A","text":"只有红细胞"},{"key":"B","text":"血清和氧气"},{"key":"C","text":"血浆和血细胞"},{"key":"D","text":"淋巴和胆汁"}],"a":"C","ex":"血细胞包括红细胞、白细胞和血小板。"},{"id":"cnb_j037_q2","tid":"cnb_j037","ty":"choice","df":"basic","p":"运输氧的血细胞是？","ch":[{"key":"A","text":"白细胞"},{"key":"B","text":"血小板"},{"key":"C","text":"血浆中的纤维蛋白"},{"key":"D","text":"红细胞"}],"a":"D","ex":"红细胞里的血红蛋白在氧含量高的地方与氧结合，在氧含量低的地方释放氧。"},{"id":"cnb_j037_q3","tid":"cnb_j037","ty":"choice","df":"standard","p":"人体受伤后能够止血，与哪种血细胞有关？","ch":[{"key":"A","text":"血小板"},{"key":"B","text":"只有白细胞"},{"key":"C","text":"成熟红细胞有细胞核所以能止血"},{"key":"D","text":"叶绿体"}],"a":"A","ex":"血小板在伤口处聚集成团并促进凝血。"},{"id":"cnb_j037_q4","tid":"cnb_j037","ty":"choice","df":"challenge","p":"医生说某人贫血，通常是指？","ch":[{"key":"A","text":"白细胞过多"},{"key":"B","text":"红细胞数量过少或血红蛋白含量过低"},{"key":"C","text":"血小板过多"},{"key":"D","text":"血浆中水太多"}],"a":"B","ex":"血红蛋白或红细胞不足，血液运输氧的能力下降。"},{"id":"cnb_j038_q1","tid":"cnb_j038","ty":"choice","df":"basic","p":"把血液从心脏送到全身各处的血管是？","ch":[{"key":"A","text":"静脉"},{"key":"B","text":"毛细血管"},{"key":"C","text":"淋巴管"},{"key":"D","text":"动脉"}],"a":"D","ex":"动脉管壁厚、弹性大，血流速度快。"},{"id":"cnb_j038_q2","tid":"cnb_j038","ty":"choice","df":"basic","p":"静脉中防止血液倒流的结构是？","ch":[{"key":"A","text":"静脉瓣"},{"key":"B","text":"动脉瓣位于静脉中"},{"key":"C","text":"声带"},{"key":"D","text":"会厌软骨"}],"a":"A","ex":"四肢静脉的内表面有静脉瓣，使血液只能流回心脏。"},{"id":"cnb_j038_q3","tid":"cnb_j038","ty":"choice","df":"standard","p":"毛细血管适于物质交换，是因为？","ch":[{"key":"A","text":"管壁最厚"},{"key":"B","text":"管壁只由一层上皮细胞构成，血流速度慢，只允许红细胞单行通过"},{"key":"C","text":"血流速度最快"},{"key":"D","text":"里面没有血液"}],"a":"B","ex":"营养物质和氧透过这层细胞进入组织细胞，废物和二氧化碳进入血液。"},{"id":"cnb_j038_q4","tid":"cnb_j038","ty":"choice","df":"challenge","p":"肺动脉里流的是？","ch":[{"key":"A","text":"动脉血"},{"key":"B","text":"只含氧气、不含二氧化碳的水"},{"key":"C","text":"静脉血"},{"key":"D","text":"淋巴"}],"a":"C","ex":"肺动脉把右心室的静脉血送到肺；名称里的「动脉」指的是从心脏发出，不是血液含氧多少。"},{"id":"cnb_j039_q1","tid":"cnb_j039","ty":"choice","df":"basic","p":"心脏四个腔中，壁最厚的是？","ch":[{"key":"A","text":"左心室"},{"key":"B","text":"右心室"},{"key":"C","text":"左心房"},{"key":"D","text":"右心房"}],"a":"A","ex":"左心室要把血液压到全身，所以肌肉壁最厚。"},{"id":"cnb_j039_q2","tid":"cnb_j039","ty":"choice","df":"basic","p":"心房和心室之间的瓣膜保证血液？","ch":[{"key":"A","text":"由心室流回心房"},{"key":"B","text":"由心房流向心室，不会倒流"},{"key":"C","text":"在四个腔里来回流动"},{"key":"D","text":"直接从左心室进入右心室"}],"a":"B","ex":"心室与动脉之间也有瓣膜，防止血液从动脉流回心室。"},{"id":"cnb_j039_q3","tid":"cnb_j039","ty":"choice","df":"standard","p":"体循环的路径是？","ch":[{"key":"A","text":"右心室、肺动脉、肺、肺静脉、左心房"},{"key":"B","text":"左心房直接到右心房"},{"key":"C","text":"左心室、主动脉、全身毛细血管、上下腔静脉、右心房"},{"key":"D","text":"右心房、主动脉、肺、左心室"}],"a":"C","ex":"体循环把氧和营养送到全身，血液由动脉血变成静脉血。"},{"id":"cnb_j039_q4","tid":"cnb_j039","ty":"choice","df":"challenge","p":"经过肺循环后，血液发生的变化是？","ch":[{"key":"A","text":"动脉血变成静脉血"},{"key":"B","text":"血液不再含有二氧化碳"},{"key":"C","text":"血细胞全部留在肺泡"},{"key":"D","text":"静脉血变成动脉血"}],"a":"D","ex":"肺循环中血液在肺部获得氧、排出二氧化碳。"},{"id":"cnb_j040_q1","tid":"cnb_j040","ty":"choice","df":"basic","p":"排泄是指排出？","ch":[{"key":"A","text":"没有消化的食物残渣"},{"key":"B","text":"二氧化碳、尿素和多余的水、无机盐等代谢废物"},{"key":"C","text":"全部血液"},{"key":"D","text":"只排出粪便"}],"a":"B","ex":"粪便是排遗，不是排泄；排泄经过呼吸、泌尿和皮肤等途径。"},{"id":"cnb_j040_q2","tid":"cnb_j040","ty":"choice","df":"basic","p":"泌尿系统包括？","ch":[{"key":"A","text":"心脏、血管和血液"},{"key":"B","text":"肺、气管和支气管"},{"key":"C","text":"肾、输尿管、膀胱和尿道"},{"key":"D","text":"胃、肠和肝"}],"a":"C","ex":"肾形成尿液，输尿管输送，膀胱暂时储存，尿道排出。"},{"id":"cnb_j040_q3","tid":"cnb_j040","ty":"choice","df":"standard","p":"尿液形成时，肾小球和肾小囊内壁的滤过作用发生在？","ch":[{"key":"A","text":"膀胱"},{"key":"B","text":"尿道"},{"key":"C","text":"皮肤"},{"key":"D","text":"肾单位"}],"a":"D","ex":"肾单位包括肾小球、肾小囊和肾小管，是形成尿液的结构单位。"},{"id":"cnb_j040_q4","tid":"cnb_j040","ty":"choice","df":"challenge","p":"健康人原尿中的葡萄糖，经过肾小管后通常？","ch":[{"key":"A","text":"被全部重吸收"},{"key":"B","text":"全部留在尿液里"},{"key":"C","text":"变成血细胞"},{"key":"D","text":"直接排出体外约 180 升"}],"a":"A","ex":"肾小管重吸收全部葡萄糖、大部分水和部分无机盐；每天形成的尿液大约只有 1.5 升。"},{"id":"cnb_j041_q1","tid":"cnb_j041","ty":"choice","df":"basic","p":"外界物体反射来的光线，在眼球里成像的部位是？","ch":[{"key":"A","text":"晶状体"},{"key":"B","text":"角膜"},{"key":"C","text":"视网膜"},{"key":"D","text":"玻璃体"}],"a":"C","ex":"晶状体相当于镜头，视网膜相当于底片，成像在视网膜上。"},{"id":"cnb_j041_q2","tid":"cnb_j041","ty":"choice","df":"basic","p":"听觉感受器位于？","ch":[{"key":"A","text":"鼓膜"},{"key":"B","text":"耳郭"},{"key":"C","text":"听小骨"},{"key":"D","text":"耳蜗"}],"a":"D","ex":"声波经外耳道、鼓膜和听小骨传到内耳，刺激耳蜗内的感受器。"},{"id":"cnb_j041_q3","tid":"cnb_j041","ty":"choice","df":"standard","p":"看近处物体时，晶状体的变化是？","ch":[{"key":"A","text":"曲度变大"},{"key":"B","text":"曲度变小"},{"key":"C","text":"完全停止调节"},{"key":"D","text":"移到视网膜后面"}],"a":"A","ex":"睫状肌收缩，晶状体曲度变大，近处物体才能清楚成像。"},{"id":"cnb_j041_q4","tid":"cnb_j041","ty":"choice","df":"challenge","p":"近视若是眼球前后径过长或晶状体曲度过大，物像落在视网膜前方，应佩戴？","ch":[{"key":"A","text":"凸透镜"},{"key":"B","text":"凹透镜"},{"key":"C","text":"平面镜"},{"key":"D","text":"放大镜"}],"a":"B","ex":"凹透镜使光线发散后再进入眼球，使物像后移到视网膜上。"},{"id":"cnb_j042_q1","tid":"cnb_j042","ty":"choice","df":"basic","p":"完成反射的神经结构是？","ch":[{"key":"A","text":"只有大脑"},{"key":"B","text":"只有一根神经"},{"key":"C","text":"骨骼"},{"key":"D","text":"反射弧"}],"a":"D","ex":"反射弧包括感受器、传入神经、神经中枢、传出神经和效应器。"},{"id":"cnb_j042_q2","tid":"cnb_j042","ty":"choice","df":"basic","p":"膝跳反射的神经中枢位于？","ch":[{"key":"A","text":"脊髓"},{"key":"B","text":"大脑皮层"},{"key":"C","text":"小脑"},{"key":"D","text":"耳蜗"}],"a":"A","ex":"膝跳反射是简单反射，神经中枢在脊髓。"},{"id":"cnb_j042_q3","tid":"cnb_j042","ty":"choice","df":"standard","p":"望梅止渴属于？","ch":[{"key":"A","text":"生来就有的简单反射"},{"key":"B","text":"复杂反射，要经过后天学习"},{"key":"C","text":"不需要大脑皮层参与"},{"key":"D","text":"只靠激素、不靠神经"}],"a":"B","ex":"在吃过梅的经验之后，看到梅就能分泌唾液，这是后天形成的复杂反射。"},{"id":"cnb_j042_q4","tid":"cnb_j042","ty":"choice","df":"challenge","p":"如果反射弧中的传入神经受损，刺激感受器后？","ch":[{"key":"A","text":"反射仍然完整"},{"key":"B","text":"只有效应器自己收缩、与神经无关"},{"key":"C","text":"不能产生反射"},{"key":"D","text":"神经中枢会直接看到刺激"}],"a":"C","ex":"反射弧的五个部分缺一不可，冲动到不了神经中枢。"},{"id":"cnb_j043_q1","tid":"cnb_j043","ty":"choice","df":"basic","p":"运动系统主要由哪些结构组成？","ch":[{"key":"A","text":"骨、关节和骨骼肌"},{"key":"B","text":"只有肌肉"},{"key":"C","text":"脑、脊髓和神经"},{"key":"D","text":"心脏和血管"}],"a":"A","ex":"骨是杠杆，关节是支点，骨骼肌提供动力。"},{"id":"cnb_j043_q2","tid":"cnb_j043","ty":"choice","df":"basic","p":"骨骼肌接受刺激后的反应是？","ch":[{"key":"A","text":"既拉长又主动推开骨"},{"key":"B","text":"收缩"},{"key":"C","text":"变成神经"},{"key":"D","text":"停止血液循环"}],"a":"B","ex":"一组骨骼肌只能收缩牵拉骨，不能主动伸长把骨推开。"},{"id":"cnb_j043_q3","tid":"cnb_j043","ty":"choice","df":"standard","p":"屈肘时，肱二头肌和肱三头肌的状态是？","ch":[{"key":"A","text":"两块肌肉同时收缩"},{"key":"B","text":"两块肌肉同时舒张"},{"key":"C","text":"肱二头肌收缩，肱三头肌舒张"},{"key":"D","text":"肱二头肌舒张，肱三头肌收缩"}],"a":"C","ex":"屈肘和伸肘由这组肌肉互相配合完成。"},{"id":"cnb_j043_q4","tid":"cnb_j043","ty":"choice","df":"challenge","p":"关节里减少摩擦的结构是？","ch":[{"key":"A","text":"骨髓"},{"key":"B","text":"骨膜里的神经"},{"key":"C","text":"肌腹"},{"key":"D","text":"关节软骨和关节腔内的滑液"}],"a":"D","ex":"关节面覆盖软骨，关节囊分泌滑液，使运动更灵活。"},{"id":"cnb_j044_q1","tid":"cnb_j044","ty":"choice","df":"basic","p":"幼年时期生长激素分泌不足，可能患？","ch":[{"key":"A","text":"呆小症"},{"key":"B","text":"侏儒症"},{"key":"C","text":"糖尿病"},{"key":"D","text":"甲亢"}],"a":"B","ex":"侏儒症智力一般正常；幼年甲状腺激素不足才会患呆小症，智力受影响。"},{"id":"cnb_j044_q2","tid":"cnb_j044","ty":"choice","df":"basic","p":"胰岛素的主要作用是？","ch":[{"key":"A","text":"促进生长发育"},{"key":"B","text":"提高神经系统兴奋性"},{"key":"C","text":"降低血糖"},{"key":"D","text":"促进生殖器官发育"}],"a":"C","ex":"胰岛素由胰岛分泌，能促进组织细胞摄取和利用葡萄糖。"},{"id":"cnb_j044_q3","tid":"cnb_j044","ty":"choice","df":"standard","p":"体内缺碘，合成甲状腺激素的原料不足，可能引起？","ch":[{"key":"A","text":"侏儒症"},{"key":"B","text":"坏血病"},{"key":"C","text":"夜盲症"},{"key":"D","text":"地方性甲状腺肿"}],"a":"D","ex":"甲状腺激素的合成需要碘；缺碘时甲状腺会代偿性增生。"},{"id":"cnb_j044_q4","tid":"cnb_j044","ty":"choice","df":"challenge","p":"神经调节和激素调节相比？","ch":[{"key":"A","text":"神经调节迅速、准确，激素调节作用时间通常较长"},{"key":"B","text":"激素调节不需要体液运输"},{"key":"C","text":"两者不能配合"},{"key":"D","text":"只有激素能对刺激作出反应"}],"a":"A","ex":"人体以神经调节为主，激素调节配合，共同维持稳定。"},{"id":"cnb_j045_q1","tid":"cnb_j045","ty":"choice","df":"basic","p":"传染病流行必须同时具备？","ch":[{"key":"A","text":"只有易感人群"},{"key":"B","text":"只有病原体、没有传染源"},{"key":"C","text":"传染源、传播途径和易感人群"},{"key":"D","text":"健康的生活环境就一定会流行"}],"a":"C","ex":"三个环节缺少任何一个，传染病就不能在人群中流行。"},{"id":"cnb_j045_q2","tid":"cnb_j045","ty":"choice","df":"basic","p":"对患传染病的人进行隔离治疗，属于？","ch":[{"key":"A","text":"切断传播途径"},{"key":"B","text":"保护易感人群"},{"key":"C","text":"增加易感者"},{"key":"D","text":"控制传染源"}],"a":"D","ex":"传染源是能够散播病原体的人或动物；隔离是为了控制传染源。"},{"id":"cnb_j045_q3","tid":"cnb_j045","ty":"choice","df":"standard","p":"开窗通风、食物器具消毒，主要是？","ch":[{"key":"A","text":"切断传播途径"},{"key":"B","text":"控制全部易感人群的遗传物质"},{"key":"C","text":"消灭所有人体细胞"},{"key":"D","text":"代替接种疫苗"}],"a":"A","ex":"这些做法减少病原体从传染源到达健康人的机会。"},{"id":"cnb_j045_q4","tid":"cnb_j045","ty":"choice","df":"challenge","p":"艾滋病病毒主要不会通过哪一方式传播？","ch":[{"key":"A","text":"输入含病毒的血液"},{"key":"B","text":"一起进餐和握手"},{"key":"C","text":"不安全性行为"},{"key":"D","text":"母婴传播"}],"a":"B","ex":"艾滋病通过血液、性接触和母婴传播；一般握手、共同进餐不会感染。"},{"id":"cnb_j046_q1","tid":"cnb_j046","ty":"choice","df":"basic","p":"皮肤和黏膜阻挡病原体，属于？","ch":[{"key":"A","text":"第三道防线"},{"key":"B","text":"特异性免疫"},{"key":"C","text":"免疫规划"},{"key":"D","text":"第一道防线"}],"a":"D","ex":"第一道防线是皮肤和黏膜；体液中的杀菌物质和吞噬细胞是第二道防线。"},{"id":"cnb_j046_q2","tid":"cnb_j046","ty":"choice","df":"basic","p":"接种疫苗后产生抗体，这种免疫是？","ch":[{"key":"A","text":"特异性免疫"},{"key":"B","text":"第一道防线"},{"key":"C","text":"生来就有、对所有病原体完全相同的非特异性免疫"},{"key":"D","text":"只由皮肤完成"}],"a":"A","ex":"疫苗相当于抗原，促使淋巴细胞产生相应抗体，只针对特定病原体。"},{"id":"cnb_j046_q3","tid":"cnb_j046","ty":"choice","df":"standard","p":"按规定有计划地接种疫苗，叫做？","ch":[{"key":"A","text":"控制传染源的隔离"},{"key":"B","text":"免疫规划"},{"key":"C","text":"非处方药治疗"},{"key":"D","text":"反射弧"}],"a":"B","ex":"免疫规划是保护易感人群的重要措施。"},{"id":"cnb_j046_q4","tid":"cnb_j046","ty":"choice","df":"challenge","p":"免疫的功能不包括？","ch":[{"key":"A","text":"抵抗抗原的侵入"},{"key":"B","text":"清除体内衰老、死亡的细胞"},{"key":"C","text":"制造病原体让疾病流行"},{"key":"D","text":"监视并清除异常细胞"}],"a":"C","ex":"免疫有防御、自稳和监视功能；免疫过强可能引起过敏或自身免疫病。"},{"id":"cnb_j047_q1","tid":"cnb_j047","ty":"choice","df":"basic","p":"非处方药的英文简称是？","ch":[{"key":"A","text":"OTC"},{"key":"B","text":"DNA"},{"key":"C","text":"HIV"},{"key":"D","text":"AQI"}],"a":"A","ex":"OTC 可以按说明书自行购买使用；处方药必须凭医师处方。"},{"id":"cnb_j047_q2","tid":"cnb_j047","ty":"choice","df":"basic","p":"用药时正确的做法是？","ch":[{"key":"A","text":"把几种药一起加倍服用"},{"key":"B","text":"按说明书或医嘱使用，不随意加大剂量"},{"key":"C","text":"过期药只要没有变色就可以吃"},{"key":"D","text":"用别人的处方药给自己治病"}],"a":"B","ex":"加大剂量或服用过期药都可能造成伤害。"},{"id":"cnb_j047_q3","tid":"cnb_j047","ty":"choice","df":"standard","p":"动脉出血时，止血带应压迫在？","ch":[{"key":"A","text":"伤口的远心端"},{"key":"B","text":"手指末端无论伤口在哪里"},{"key":"C","text":"伤口的近心端"},{"key":"D","text":"只压迫静脉的远心端"}],"a":"C","ex":"动脉血从心脏流向伤口，近心端压迫才能阻断来血；静脉出血则压远心端。"},{"id":"cnb_j047_q4","tid":"cnb_j047","ty":"choice","df":"challenge","p":"发现有人煤气中毒，首先应？","ch":[{"key":"A","text":"在密闭房间里点火查看"},{"key":"B","text":"让中毒者继续躺在泄漏点旁边"},{"key":"C","text":"先喂食物再开门"},{"key":"D","text":"打开门窗，把人移到通风处，再拨打急救电话"}],"a":"D","ex":"煤气的主要成分一氧化碳会与血红蛋白结合；先脱离现场并保持呼吸通畅。"},{"id":"cnb_j048_q1","tid":"cnb_j048","ty":"choice","df":"basic","p":"健康的生活方式包括？","ch":[{"key":"A","text":"用吸烟提神"},{"key":"B","text":"均衡营养、坚持锻炼、不吸烟、不酗酒、拒绝毒品"},{"key":"C","text":"每天只睡很少时间"},{"key":"D","text":"靠饮料代替饮水"}],"a":"B","ex":"这些习惯能降低心血管疾病和部分癌症的风险。"},{"id":"cnb_j048_q2","tid":"cnb_j048","ty":"choice","df":"basic","p":"酗酒对人体危害最大的系统之一是？","ch":[{"key":"A","text":"可以保护肝脏"},{"key":"B","text":"只影响头发颜色"},{"key":"C","text":"神经系统"},{"key":"D","text":"使免疫力无限提高"}],"a":"C","ex":"酒精麻痹神经系统，长期饮酒还会损害肝脏和心血管。"},{"id":"cnb_j048_q3","tid":"cnb_j048","ty":"choice","df":"standard","p":"毒品危害健康，根本原因是？","ch":[{"key":"A","text":"可以代替一日三餐"},{"key":"B","text":"能提高学习效率且没有依赖"},{"key":"C","text":"只影响皮肤颜色"},{"key":"D","text":"损害神经系统，而且容易成瘾"}],"a":"D","ex":"毒品会损害脑和神经系统，一旦成瘾很难戒断。"},{"id":"cnb_j048_q4","tid":"cnb_j048","ty":"choice","df":"challenge","p":"为了降低心血管疾病的风险，合适的做法是？","ch":[{"key":"A","text":"少吃高脂食物，经常运动，不吸烟"},{"key":"B","text":"用静坐代替所有活动"},{"key":"C","text":"每天大量饮酒"},{"key":"D","text":"自行长期服用未经医生同意的激素"}],"a":"A","ex":"生活方式与心血管疾病、癌症有关，预防要从饮食、运动和戒烟做起。"},{"id":"cnb_j049_q1","tid":"cnb_j049","ty":"choice","df":"basic","p":"影响生物生活的非生物因素包括？","ch":[{"key":"A","text":"只有食物链"},{"key":"B","text":"只有捕食关系"},{"key":"C","text":"光、温度、水和空气"},{"key":"D","text":"分类等级"}],"a":"C","ex":"非生物因素和生物因素合称生态因素。"},{"id":"cnb_j049_q2","tid":"cnb_j049","ty":"choice","df":"basic","p":"鼠妇适于生活在？","ch":[{"key":"A","text":"强光干燥的地方"},{"key":"B","text":"开水里"},{"key":"C","text":"没有空气的密封罐"},{"key":"D","text":"阴暗潮湿的地方"}],"a":"D","ex":"探究实验中，鼠妇较多集中在阴暗潮湿一侧。"},{"id":"cnb_j049_q3","tid":"cnb_j049","ty":"choice","df":"standard","p":"蚯蚓在土壤中活动，能使土壤更疏松，这说明？","ch":[{"key":"A","text":"生物能影响环境"},{"key":"B","text":"环境对生物没有任何作用"},{"key":"C","text":"生物不能适应环境"},{"key":"D","text":"只有非生物因素起作用"}],"a":"A","ex":"生物既受环境限制，也会改变环境。"},{"id":"cnb_j049_q4","tid":"cnb_j049","ty":"choice","df":"challenge","p":"沙漠中的骆驼尿液很少、体温可以在一定范围内变化，主要说明？","ch":[{"key":"A","text":"生物不需要水"},{"key":"B","text":"生物能适应环境"},{"key":"C","text":"环境不会影响生物"},{"key":"D","text":"骆驼不属于生物"}],"a":"B","ex":"这些特征有利于在缺水、昼夜温差大的环境中生活。"},{"id":"cnb_j050_q1","tid":"cnb_j050","ty":"choice","df":"basic","p":"生态系统中，能把无机物制造成有机物的是？","ch":[{"key":"A","text":"消费者"},{"key":"B","text":"分解者"},{"key":"C","text":"非生物部分里的石头"},{"key":"D","text":"生产者"}],"a":"D","ex":"生产者主要是绿色植物，是食物链的起点。"},{"id":"cnb_j050_q2","tid":"cnb_j050","ty":"choice","df":"basic","p":"细菌和真菌在生态系统中主要作为？","ch":[{"key":"A","text":"分解者"},{"key":"B","text":"生产者"},{"key":"C","text":"消费者中的最高营养级"},{"key":"D","text":"非生物成分"}],"a":"A","ex":"分解者把动植物遗体里的有机物分解成无机物，供生产者重新利用。"},{"id":"cnb_j050_q3","tid":"cnb_j050","ty":"choice","df":"standard","p":"一条食物链「草→兔→狐」中，能量流动的特点是？","ch":[{"key":"A","text":"循环利用且越来越多"},{"key":"B","text":"单向流动、逐级递减"},{"key":"C","text":"从狐流向草"},{"key":"D","text":"每个营养级获得的能量相同"}],"a":"B","ex":"能量沿食物链传递时大部分被消耗，营养级越高，获得的能量越少。"},{"id":"cnb_j050_q4","tid":"cnb_j050","ty":"choice","df":"challenge","p":"有毒物质进入食物链后，浓度通常最高的是？","ch":[{"key":"A","text":"生产者"},{"key":"B","text":"空气"},{"key":"C","text":"营养级最高的生物"},{"key":"D","text":"分解者一定最低且不受影响"}],"a":"C","ex":"有毒物质不易分解，会沿着食物链积累。"},{"id":"cnb_j051_q1","tid":"cnb_j051","ty":"choice","df":"basic","p":"生物圈的范围大致包括？","ch":[{"key":"A","text":"大气圈的底部、水圈的大部和岩石圈的表面"},{"key":"B","text":"只有海洋"},{"key":"C","text":"只有地面以上 1 米"},{"key":"D","text":"地核"}],"a":"A","ex":"绝大多数生物生活在这三部分交界的范围内。"},{"id":"cnb_j051_q2","tid":"cnb_j051","ty":"choice","df":"basic","p":"生物圈是？","ch":[{"key":"A","text":"最小的一个细胞"},{"key":"B","text":"地球上最大的生态系统"},{"key":"C","text":"一种组织"},{"key":"D","text":"一个器官"}],"a":"B","ex":"森林、草原、海洋、湿地等都是生物圈中的生态系统。"},{"id":"cnb_j051_q3","tid":"cnb_j051","ty":"choice","df":"standard","p":"生物生存需要的基本条件包括？","ch":[{"key":"A","text":"只需要土壤的颜色"},{"key":"B","text":"只需要重力"},{"key":"C","text":"营养物质、阳光、空气、水和适宜的温度"},{"key":"D","text":"不需要空间"}],"a":"C","ex":"还需要一定的生存空间；缺少这些条件，生物就不能正常生活。"},{"id":"cnb_j051_q4","tid":"cnb_j051","ty":"choice","df":"challenge","p":"像生物圈那样为生物提供生存条件的整体，在目前已知范围内？","ch":[{"key":"A","text":"太阳系每颗行星都有"},{"key":"B","text":"月球表面已经具备"},{"key":"C","text":"可以不依赖能量输入"},{"key":"D","text":"地球是唯一的"}],"a":"D","ex":"保护生物圈就是保护人类自己的家园。"},{"id":"cnb_j052_q1","tid":"cnb_j052","ty":"choice","df":"basic","p":"大量砍伐森林后，较容易引起？","ch":[{"key":"A","text":"空气中的氧气无限增加"},{"key":"B","text":"水土流失"},{"key":"C","text":"当地降水量必定升高且不再变化"},{"key":"D","text":"生物种类一定增多"}],"a":"B","ex":"植被破坏后，土壤失去保护，雨水更容易把泥土冲走。"},{"id":"cnb_j052_q2","tid":"cnb_j052","ty":"choice","df":"basic","p":"随意引进外来物种，可能？","ch":[{"key":"A","text":"一定使本地生物全部受益"},{"key":"B","text":"不会繁殖"},{"key":"C","text":"挤占本地生物的生存空间"},{"key":"D","text":"自动提高生态系统的调节能力且没有上限"}],"a":"C","ex":"缺少天敌时，外来物种可能大量繁殖，破坏原有的食物关系。"},{"id":"cnb_j052_q3","tid":"cnb_j052","ty":"choice","df":"standard","p":"工厂把未经处理的污水排进河流，直接影响的是？","ch":[{"key":"A","text":"只会让水中的氧气自动增多"},{"key":"B","text":"与人类健康无关"},{"key":"C","text":"使有毒物质沿食物链越来越少"},{"key":"D","text":"水生生物的生存和下游的用水安全"}],"a":"D","ex":"污染会通过饮水和食物链影响其他生物和人。"},{"id":"cnb_j052_q4","tid":"cnb_j052","ty":"choice","df":"challenge","p":"分析「围湖造田」的影响，较合理的结论是？","ch":[{"key":"A","text":"湖泊调蓄洪水和净化水质的能力下降"},{"key":"B","text":"湖泊生物一定增多"},{"key":"C","text":"当地气候完全不受影响"},{"key":"D","text":"围得越大，生态系统越稳定"}],"a":"A","ex":"湖泊是生态系统，缩小湖面就会削弱它的生态功能。"},{"id":"cnb_j053_q1","tid":"cnb_j053","ty":"choice","df":"basic","p":"维护生态安全，较合适的做法是？","ch":[{"key":"A","text":"把所有野生动物都关进家里饲养"},{"key":"B","text":"继续向河流排放污水"},{"key":"C","text":"保护植被、治理污染、防止外来物种随意扩散"},{"key":"D","text":"锯掉全部森林改成裸地"}],"a":"C","ex":"生态安全关心的是生态系统能否保持完整并持续提供服务。"},{"id":"cnb_j053_q2","tid":"cnb_j053","ty":"choice","df":"basic","p":"保护当地的森林和湿地，属于？","ch":[{"key":"A","text":"把全部生物迁到外地"},{"key":"B","text":"只保护一种观赏植物的花色"},{"key":"C","text":"停止一切科学观察"},{"key":"D","text":"就地维护生态系统"}],"a":"D","ex":"保护栖息地，比把生物全部搬走更能维持原有的生态关系。"},{"id":"cnb_j053_q3","tid":"cnb_j053","ty":"choice","df":"standard","p":"垃圾分类的作用是？","ch":[{"key":"A","text":"减少污染，便于回收可利用的物质"},{"key":"B","text":"让有害垃圾直接进入农田"},{"key":"C","text":"代替污水处理"},{"key":"D","text":"使塑料在自然界中立刻消失"}],"a":"A","ex":"分类投放可以减少有害物质进入土壤和水体。"},{"id":"cnb_j053_q4","tid":"cnb_j053","ty":"choice","df":"challenge","p":"某地为了增加粮食而毁林开荒，后来洪水和沙尘加重。更可取的做法是？","ch":[{"key":"A","text":"继续扩大开荒"},{"key":"B","text":"退耕还林，恢复植被"},{"key":"C","text":"把河水全部截断"},{"key":"D","text":"引入没有检验的外来植物"}],"a":"B","ex":"恢复植被有利于保持水土，也有利于维护生态安全。"},{"id":"cnb_j054_q1","tid":"cnb_j054","ty":"choice","df":"basic","p":"无性生殖的特点是？","ch":[{"key":"A","text":"必须经过精子和卵细胞结合"},{"key":"B","text":"后代一定具有双亲的遗传特性"},{"key":"C","text":"只存在于动物"},{"key":"D","text":"不经过两性生殖细胞的结合"}],"a":"D","ex":"扦插、嫁接、组织培养以及酵母菌的出芽生殖都属于无性生殖。"},{"id":"cnb_j054_q2","tid":"cnb_j054","ty":"choice","df":"basic","p":"用葡萄的一段枝条插入土壤长成新植株，这种生殖方式是？","ch":[{"key":"A","text":"扦插"},{"key":"B","text":"种子繁殖"},{"key":"C","text":"出芽形成受精卵"},{"key":"D","text":"分裂产生精子"}],"a":"A","ex":"扦插使用的是营养器官，没有两性生殖细胞的结合。"},{"id":"cnb_j054_q3","tid":"cnb_j054","ty":"choice","df":"standard","p":"嫁接时，成活的关键是？","ch":[{"key":"A","text":"接穗和砧木换成同一种花瓣颜色即可，形成层可以分开"},{"key":"B","text":"接穗和砧木的形成层紧贴"},{"key":"C","text":"只把叶贴在一起"},{"key":"D","text":"让接穗先完成受精"}],"a":"B","ex":"形成层的细胞能分裂，长出新组织，使接穗和砧木长在一起。"},{"id":"cnb_j054_q4","tid":"cnb_j054","ty":"choice","df":"challenge","p":"用无性生殖培育果树，主要优点是？","ch":[{"key":"A","text":"后代一定比母体更适应一切环境"},{"key":"B","text":"必须经过开花传粉"},{"key":"C","text":"后代能保持母体的优良性状"},{"key":"D","text":"变异一定比有性生殖更大"}],"a":"C","ex":"后代的遗传物质主要来自母体，优良特性不容易被另一亲本改变。"},{"id":"cnb_j055_q1","tid":"cnb_j055","ty":"choice","df":"basic","p":"有性生殖必须经过？","ch":[{"key":"A","text":"两性生殖细胞结合"},{"key":"B","text":"扦插"},{"key":"C","text":"嫁接"},{"key":"D","text":"出芽"}],"a":"A","ex":"精子和卵细胞结合形成受精卵，由受精卵发育成新个体。"},{"id":"cnb_j055_q2","tid":"cnb_j055","ty":"choice","df":"basic","p":"有性生殖的后代？","ch":[{"key":"A","text":"只保留母本性状、与父本无关"},{"key":"B","text":"具有双亲的遗传特性"},{"key":"C","text":"与亲代没有任何相同点"},{"key":"D","text":"不能变异"}],"a":"B","ex":"两性生殖细胞各带一份遗传物质，后代因此具有双亲的特征。"},{"id":"cnb_j055_q3","tid":"cnb_j055","ty":"choice","df":"standard","p":"被子植物经过开花、传粉和受精后，种子里的胚由什么发育而来？","ch":[{"key":"A","text":"花瓣"},{"key":"B","text":"叶肉细胞直接变来"},{"key":"C","text":"受精卵"},{"key":"D","text":"花粉管的壁"}],"a":"C","ex":"受精卵发育成胚，胚珠发育成种子，子房发育成果实。"},{"id":"cnb_j055_q4","tid":"cnb_j055","ty":"choice","df":"challenge","p":"与无性生殖相比，有性生殖的意义主要是？","ch":[{"key":"A","text":"后代永远和母体一模一样"},{"key":"B","text":"不需要生殖细胞"},{"key":"C","text":"速度在任何情况下都更快"},{"key":"D","text":"后代变异更多，更有利于适应变化的环境"}],"a":"D","ex":"遗传物质来自双亲，后代的差异通常更大。"},{"id":"cnb_j056_q1","tid":"cnb_j056","ty":"choice","df":"basic","p":"基因是？","ch":[{"key":"A","text":"一条染色体上的全部蛋白质"},{"key":"B","text":"有遗传效应的 DNA 片段"},{"key":"C","text":"细胞壁的主要成分"},{"key":"D","text":"一种维生素"}],"a":"B","ex":"染色体主要由 DNA 和蛋白质组成，基因是 DNA 上控制性状的区段。"},{"id":"cnb_j056_q2","tid":"cnb_j056","ty":"choice","df":"basic","p":"把大鼠生长激素基因转入小鼠体内，小鼠长得很大，说明？","ch":[{"key":"A","text":"性状只由食物决定，与基因无关"},{"key":"B","text":"DNA 不是遗传物质"},{"key":"C","text":"基因控制生物的性状"},{"key":"D","text":"基因不能从一个细胞进入另一个细胞"}],"a":"C","ex":"转入的基因使小鼠表现出相应性状。"},{"id":"cnb_j056_q3","tid":"cnb_j056","ty":"choice","df":"standard","p":"同卵双生的兄弟，一个长期锻炼、一个很少运动，肌肉发达程度不同，说明？","ch":[{"key":"A","text":"基因会因为锻炼立刻全部改变"},{"key":"B","text":"两人的基因完全不同"},{"key":"C","text":"环境不能影响任何性状"},{"key":"D","text":"性状还受环境的影响"}],"a":"D","ex":"基因提供了发育的可能，环境会影响性状的表现。"},{"id":"cnb_j056_q4","tid":"cnb_j056","ty":"choice","df":"challenge","p":"生物体内的遗传物质主要是？","ch":[{"key":"A","text":"DNA"},{"key":"B","text":"脂肪"},{"key":"C","text":"淀粉"},{"key":"D","text":"纤维素"}],"a":"A","ex":"DNA 携带遗传信息；基因是有遗传效应的 DNA 片段。"},{"id":"cnb_j057_q1","tid":"cnb_j057","ty":"choice","df":"basic","p":"人的体细胞中染色体数目是？","ch":[{"key":"A","text":"23 条"},{"key":"B","text":"46 对"},{"key":"C","text":"23 对"},{"key":"D","text":"92 对"}],"a":"C","ex":"体细胞中染色体成对存在，人有 23 对、46 条。"},{"id":"cnb_j057_q2","tid":"cnb_j057","ty":"choice","df":"basic","p":"生殖细胞中的染色体数目是体细胞的？","ch":[{"key":"A","text":"两倍"},{"key":"B","text":"相同且仍然成对"},{"key":"C","text":"四分之一"},{"key":"D","text":"一半"}],"a":"D","ex":"形成生殖细胞时染色体数目减半，受精后才恢复成对。"},{"id":"cnb_j057_q3","tid":"cnb_j057","ty":"choice","df":"standard","p":"子女的染色体？","ch":[{"key":"A","text":"一半来自父方，一半来自母方"},{"key":"B","text":"全部来自母方"},{"key":"C","text":"全部来自父方"},{"key":"D","text":"只来自细胞质、不来自父母"}],"a":"A","ex":"精子和卵细胞各提供一半染色体。"},{"id":"cnb_j057_q4","tid":"cnb_j057","ty":"choice","df":"challenge","p":"基因在亲子代间传递时，主要随着什么传递？","ch":[{"key":"A","text":"细胞壁"},{"key":"B","text":"染色体"},{"key":"C","text":"食物中的蛋白质"},{"key":"D","text":"血浆"}],"a":"B","ex":"染色体上有 DNA，基因位于 DNA 上，所以基因随染色体传递。"},{"id":"cnb_j058_q1","tid":"cnb_j058","ty":"choice","df":"basic","p":"相对性状是指？","ch":[{"key":"A","text":"不同种生物的全部特征"},{"key":"B","text":"只指身高"},{"key":"C","text":"环境造成的暂时晒黑"},{"key":"D","text":"同种生物同一性状的不同表现"}],"a":"D","ex":"豌豆的高茎和矮茎、人的有耳垂和无耳垂，都是相对性状。"},{"id":"cnb_j058_q2","tid":"cnb_j058","ty":"choice","df":"basic","p":"基因组成为 Dd 时，如果 D 对 d 为显性，表现出来的是？","ch":[{"key":"A","text":"显性性状"},{"key":"B","text":"隐性性状"},{"key":"C","text":"两种性状同时各占一半身体"},{"key":"D","text":"没有性状"}],"a":"A","ex":"一对基因中只要有一个显性基因，通常就表现显性性状。"},{"id":"cnb_j058_q3","tid":"cnb_j058","ty":"choice","df":"standard","p":"隐性性状的基因组成是？","ch":[{"key":"A","text":"一个显性基因和一个隐性基因"},{"key":"B","text":"两个隐性基因"},{"key":"C","text":"两个显性基因"},{"key":"D","text":"没有基因"}],"a":"B","ex":"只有两个隐性基因在一起时，隐性性状才表现出来。"},{"id":"cnb_j058_q4","tid":"cnb_j058","ty":"choice","df":"challenge","p":"禁止近亲结婚，主要是为了？","ch":[{"key":"A","text":"让显性基因消失"},{"key":"B","text":"改变人的染色体数目"},{"key":"C","text":"降低隐性致病基因相遇的机会"},{"key":"D","text":"阻止一切变异"}],"a":"C","ex":"近亲带有相同隐性致病基因的可能性较大，后代隐性遗传病的风险更高。"},{"id":"cnb_j059_q1","tid":"cnb_j059","ty":"choice","df":"basic","p":"女性体细胞中的性染色体组成是？","ch":[{"key":"A","text":"XX"},{"key":"B","text":"XY"},{"key":"C","text":"YY"},{"key":"D","text":"XO"}],"a":"A","ex":"男性是 XY，女性是 XX。"},{"id":"cnb_j059_q2","tid":"cnb_j059","ty":"choice","df":"basic","p":"就性染色体而言，卵细胞含有？","ch":[{"key":"A","text":"一条 Y 染色体"},{"key":"B","text":"一条 X 染色体"},{"key":"C","text":"X 和 Y 各一条"},{"key":"D","text":"没有性染色体"}],"a":"B","ex":"女性只产生含 X 的卵细胞；男性产生含 X 或含 Y 的精子。"},{"id":"cnb_j059_q3","tid":"cnb_j059","ty":"choice","df":"standard","p":"生男孩还是女孩，通常取决于？","ch":[{"key":"A","text":"母亲的饮食"},{"key":"B","text":"出生的季节"},{"key":"C","text":"与卵细胞结合的精子所含的性染色体"},{"key":"D","text":"母亲的血型"}],"a":"C","ex":"含 X 的精子与卵细胞结合发育为女孩，含 Y 的精子与卵细胞结合发育为男孩。"},{"id":"cnb_j059_q4","tid":"cnb_j059","ty":"choice","df":"challenge","p":"从性染色体的组合看，生男生女的机会？","ch":[{"key":"A","text":"一定是男孩更多"},{"key":"B","text":"完全由母亲决定"},{"key":"C","text":"隔代才改变"},{"key":"D","text":"大致相等"}],"a":"D","ex":"两种精子数量大致相当，与卵细胞结合的机会也大致相等。"},{"id":"cnb_j060_q1","tid":"cnb_j060","ty":"choice","df":"basic","p":"变异是指？","ch":[{"key":"A","text":"只有亲代和子代完全相同"},{"key":"B","text":"亲子代之间以及子代个体之间的差异"},{"key":"C","text":"环境永远不变化"},{"key":"D","text":"基因不能改变"}],"a":"B","ex":"生物界普遍存在变异，变异为进化提供了原材料。"},{"id":"cnb_j060_q2","tid":"cnb_j060","ty":"choice","df":"basic","p":"花生果实有大有小，这种差异属于？","ch":[{"key":"A","text":"完全没有差异的同一性状"},{"key":"B","text":"只发生在动物身上的现象"},{"key":"C","text":"变异"},{"key":"D","text":"分类单位"}],"a":"C","ex":"同一性状在不同个体上的不同表现，就是变异。"},{"id":"cnb_j060_q3","tid":"cnb_j060","ty":"choice","df":"standard","p":"由遗传物质改变引起的变异？","ch":[{"key":"A","text":"一定不能遗传"},{"key":"B","text":"只改变当代、后代恢复原样"},{"key":"C","text":"都属于不可遗传变异"},{"key":"D","text":"可以遗传给后代"}],"a":"D","ex":"遗传物质改变引起的变异是可遗传变异。"},{"id":"cnb_j060_q4","tid":"cnb_j060","ty":"choice","df":"challenge","p":"把遗传物质相同的小麦分别种在肥沃和贫瘠的土壤里，植株高度不同。这种差异一般是？","ch":[{"key":"A","text":"环境引起的不可遗传变异"},{"key":"B","text":"染色体数目改变"},{"key":"C","text":"一定会传给下一代并在贫瘠土地上同样表现"},{"key":"D","text":"基因重组"}],"a":"A","ex":"如果遗传物质没有改变，只是水肥条件不同，这种变异一般不能遗传。"},{"id":"cnb_j061_q1","tid":"cnb_j061","ty":"choice","df":"basic","p":"原始生命诞生的场所，目前较普遍的认识是？","ch":[{"key":"A","text":"现代的陆地森林"},{"key":"B","text":"火山口的岩石内部"},{"key":"C","text":"原始海洋"},{"key":"D","text":"月球"}],"a":"C","ex":"原始海洋为早期生命提供了场所。"},{"id":"cnb_j061_q2","tid":"cnb_j061","ty":"choice","df":"basic","p":"米勒实验模拟原始大气放电后，得到了？","ch":[{"key":"A","text":"完整的动植物"},{"key":"B","text":"现代的细菌细胞核"},{"key":"C","text":"氧气成为主要成分"},{"key":"D","text":"氨基酸等有机小分子"}],"a":"D","ex":"实验说明在类似条件下，无机物可以形成有机小分子，并没有制造出生命。"},{"id":"cnb_j061_q3","tid":"cnb_j061","ty":"choice","df":"standard","p":"关于原始大气，教材中的常见说法是？","ch":[{"key":"A","text":"没有氧气"},{"key":"B","text":"以氧气为主要成分"},{"key":"C","text":"与今天的大气完全相同"},{"key":"D","text":"只含有氮气且没有其他气体"}],"a":"A","ex":"原始大气中有水蒸气、氢气、氨、甲烷、二氧化碳等，氧气是后来光合生物产生的。"},{"id":"cnb_j061_q4","tid":"cnb_j061","ty":"choice","df":"challenge","p":"研究生命起源时，化石能够？","ch":[{"key":"A","text":"直接显示明天的进化结果"},{"key":"B","text":"作为古代生物曾经生活过的证据"},{"key":"C","text":"代替全部实验"},{"key":"D","text":"证明每种现代生物都单独突然出现"}],"a":"B","ex":"地层中的化石记录了不同时期生物的样子，是研究进化的重要证据。"},{"id":"cnb_j062_q1","tid":"cnb_j062","ty":"choice","df":"basic","p":"研究生物进化历程最直接的证据之一是？","ch":[{"key":"A","text":"现在某种动物数量的多少"},{"key":"B","text":"生物的商品价格"},{"key":"C","text":"地图上的国界"},{"key":"D","text":"化石"}],"a":"D","ex":"不同地层中的化石，反映了生物出现的大致顺序。"},{"id":"cnb_j062_q2","tid":"cnb_j062","ty":"choice","df":"basic","p":"植物进化的大致历程是？","ch":[{"key":"A","text":"藻类植物，到苔藓植物和蕨类植物，再到种子植物"},{"key":"B","text":"种子植物到藻类植物"},{"key":"C","text":"只有动物进化、植物不进化"},{"key":"D","text":"真菌到哺乳动物"}],"a":"A","ex":"总体趋势是从简单到复杂、从水生到陆生。"},{"id":"cnb_j062_q3","tid":"cnb_j062","ty":"choice","df":"standard","p":"脊椎动物进化的大致顺序是？","ch":[{"key":"A","text":"哺乳类到鱼类"},{"key":"B","text":"鱼类、两栖类、爬行类，再到鸟类和哺乳类"},{"key":"C","text":"鸟类到爬行类再到鱼类"},{"key":"D","text":"两栖类直接到鱼类"}],"a":"B","ex":"鸟类和哺乳类都是由古代爬行动物进化而来的，不是鸟类变成哺乳类。"},{"id":"cnb_j062_q4","tid":"cnb_j062","ty":"choice","df":"challenge","p":"生物进化的总体趋势是？","ch":[{"key":"A","text":"由复杂到简单"},{"key":"B","text":"由陆生全部回到水生并停止变化"},{"key":"C","text":"由简单到复杂，由低等到高等，由水生到陆生"},{"key":"D","text":"每种生物都越来越大"}],"a":"C","ex":"这是总体趋势，不是说每一种现存生物都还在变成另一种。"},{"id":"cnb_j063_q1","tid":"cnb_j063","ty":"choice","df":"basic","p":"达尔文解释生物进化的学说是？","ch":[{"key":"A","text":"自然选择学说"},{"key":"B","text":"用进废退是达尔文学说的核心"},{"key":"C","text":"地球中心说"},{"key":"D","text":"细胞学说"}],"a":"A","ex":"自然选择包括过度繁殖、遗传变异、生存斗争和适者生存。"},{"id":"cnb_j063_q2","tid":"cnb_j063","ty":"choice","df":"basic","p":"长颈鹿的长颈，按自然选择学说应解释为？","ch":[{"key":"A","text":"经常伸脖子使颈变长，并且这一代就全部遗传"},{"key":"B","text":"颈长的变异能吃到高处树叶，这种有利变异被保留下来"},{"key":"C","text":"所有长颈鹿生来颈一样长，没有变异"},{"key":"D","text":"环境不能影响生存机会"}],"a":"B","ex":"拉马克用「经常使用而变长」解释；达尔文强调可遗传变异和选择。"},{"id":"cnb_j063_q3","tid":"cnb_j063","ty":"choice","df":"standard","p":"害虫抗药性增强，原因是？","ch":[{"key":"A","text":"农药使每一只害虫都主动产生抗药基因"},{"key":"B","text":"害虫喜欢农药所以变强"},{"key":"C","text":"抗药变异个体存活并繁殖，抗药性状被选择保留"},{"key":"D","text":"没有变异也能产生抗药性"}],"a":"C","ex":"农药杀死不抗药的个体，抗药个体把变异传给后代。"},{"id":"cnb_j063_q4","tid":"cnb_j063","ty":"choice","df":"challenge","p":"自然选择保留的变异是？","ch":[{"key":"A","text":"所有变异"},{"key":"B","text":"只保留有害变异"},{"key":"C","text":"环境引起、遗传物质没有改变的变异"},{"key":"D","text":"有利于生物在当时环境中生存和繁殖的可遗传变异"}],"a":"D","ex":"不利变异的个体更容易被淘汰，有利的可遗传变异更可能积累。"},{"id":"cnb_j064_q1","tid":"cnb_j064","ty":"choice","df":"basic","p":"现代类人猿和人类的共同祖先是？","ch":[{"key":"A","text":"现在的黑猩猩"},{"key":"B","text":"森林古猿"},{"key":"C","text":"现在的长臂猿"},{"key":"D","text":"恐龙"}],"a":"B","ex":"人类不是由现代黑猩猩或现代猴子变成的，而是和类人猿有共同的祖先。"},{"id":"cnb_j064_q2","tid":"cnb_j064","ty":"choice","df":"basic","p":"从古猿到人的进化中，最重要的标志是？","ch":[{"key":"A","text":"使用鳃呼吸"},{"key":"B","text":"体表长出羽毛"},{"key":"C","text":"直立行走"},{"key":"D","text":"回到四足爬行"}],"a":"C","ex":"直立行走使前肢解放出来，能够使用和制造工具。"},{"id":"cnb_j064_q3","tid":"cnb_j064","ty":"choice","df":"standard","p":"古人类在进化过程中逐渐学会？","ch":[{"key":"A","text":"用种子进行光合作用"},{"key":"B","text":"用鳃在陆地呼吸"},{"key":"C","text":"放弃群体生活"},{"key":"D","text":"制造工具和使用火"}],"a":"D","ex":"工具、火和语言的发展，与脑的发展和社会生活有关。"},{"id":"cnb_j064_q4","tid":"cnb_j064","ty":"choice","df":"challenge","p":"下列说法符合人类起源证据的是？","ch":[{"key":"A","text":"人类和现代类人猿都起源于森林古猿"},{"key":"B","text":"人是现代猴子直接生下来的"},{"key":"C","text":"世界各地的人属于不同的界"},{"key":"D","text":"人类没有哺乳动物的特征"}],"a":"A","ex":"人有毛发、胎生、哺乳，属于哺乳动物，并与类人猿亲缘关系最近。"},{"id":"cnb_j065_q1","tid":"cnb_j065","ty":"choice","df":"basic","p":"生物多样性包括？","ch":[{"key":"A","text":"只有物种数量"},{"key":"B","text":"只有森林一种生态系统"},{"key":"C","text":"基因多样性、物种多样性和生态系统多样性"},{"key":"D","text":"只指动物、不包括植物"}],"a":"C","ex":"三个层次从遗传物质、生物种类到生态系统。"},{"id":"cnb_j065_q2","tid":"cnb_j065","ty":"choice","df":"basic","p":"一个物种内部，不同个体的基因并不完全相同。这属于？","ch":[{"key":"A","text":"生态系统多样性"},{"key":"B","text":"只有物种多样性、与基因无关"},{"key":"C","text":"非生物的多样性"},{"key":"D","text":"基因多样性"}],"a":"D","ex":"基因多样性也叫遗传多样性。"},{"id":"cnb_j065_q3","tid":"cnb_j065","ty":"choice","df":"standard","p":"森林、草原、湿地和海洋提供的多样性主要属于？","ch":[{"key":"A","text":"生态系统多样性"},{"key":"B","text":"一个物种内部的全部差异"},{"key":"C","text":"分类等级中的「种」本身"},{"key":"D","text":"非生物因素的名称"}],"a":"A","ex":"不同生态系统为不同生物提供生存条件。"},{"id":"cnb_j065_q4","tid":"cnb_j065","ty":"choice","df":"challenge","p":"多种多样的生物是长期进化的结果，保护多样性首先要？","ch":[{"key":"A","text":"只记下生物的名字、可以破坏环境"},{"key":"B","text":"保护生物赖以生活的栖息地和生态系统"},{"key":"C","text":"让所有生物都变成同一个种"},{"key":"D","text":"停止对化石和分类的研究"}],"a":"B","ex":"栖息地破坏后，物种和基因多样性也会失去。"},{"id":"cnb_j066_q1","tid":"cnb_j066","ty":"choice","df":"basic","p":"保护生物多样性最有效的措施是？","ch":[{"key":"A","text":"把所有野生生物都移出原生环境"},{"key":"B","text":"只保护动物园里的动物"},{"key":"C","text":"禁止任何科学研究"},{"key":"D","text":"建立自然保护区，就地保护"}],"a":"D","ex":"就地保护能保存生物及其生存环境；迁地保护是必要的补充。"},{"id":"cnb_j066_q2","tid":"cnb_j066","ty":"choice","df":"basic","p":"将濒危动物迁到动物园繁殖，属于？","ch":[{"key":"A","text":"迁地保护"},{"key":"B","text":"就地保护"},{"key":"C","text":"引入外来物种"},{"key":"D","text":"自然选择本身"}],"a":"A","ex":"原生环境难以维持时，动物园、繁育中心和种质库可以进行迁地保护。"},{"id":"cnb_j066_q3","tid":"cnb_j066","ty":"choice","df":"standard","p":"威胁生物多样性的主要原因是？","ch":[{"key":"A","text":"生物本身拒绝进化"},{"key":"B","text":"栖息地破坏、过度利用、环境污染和外来物种入侵"},{"key":"C","text":"分类单位太多"},{"key":"D","text":"只有火山，与人类无关"}],"a":"B","ex":"人类活动是当前许多物种濒危的主要原因。"},{"id":"cnb_j066_q4","tid":"cnb_j066","ty":"choice","df":"challenge","p":"做到人与自然和谐共生，个人可以？","ch":[{"key":"A","text":"食用一切野生动物"},{"key":"B","text":"把外来生物随意放生"},{"key":"C","text":"不购买野生动物制品，并节约资源、减少污染"},{"key":"D","text":"破坏自然保护区的围栏去采集"}],"a":"C","ex":"和谐共生不是禁止认识自然，而是在利用资源时不破坏生态安全。"}];
